--[[
	References Module for Deathrun 3
	-----------------------------------------------------------------------------------------------------------
	Written by Wsly and Velibor
	Last Edit on August 6 2015 by Wsly

	Description:
	This module contains all references to instances used by frontend scripts and other modules.
	It also serves as a global WaitForChild() to ensure all instances are in memory.
]]

	local Reference 				=	{};

	local function AddToReference(Index, Value)
		Reference[Index]			=	Value;
	end

	-- Player Shortcuts
	AddToReference('Player', 			game:GetService("Players").LocalPlayer);
	AddToReference('PlayerGui', 		Reference.Player:WaitForChild("PlayerGui"));
	AddToReference('PlayerCamera', 		game.workspace.CurrentCamera);
	--AddToReference('InterfaceMain', 	Reference.PlayerGui:WaitForChild("InterfaceMain"));

	while true do
		if game.Players.LocalPlayer.PlayerGui:FindFirstChild("InterfaceMain") ~= nil then
			break;
		else
			print("[mReferences] Waiting for InterfaceMain...");
		end
		wait(.1)
	end
	AddToReference('InterfaceMain', 	Reference.PlayerGui:WaitForChild("InterfaceMain"));
	print("[mReferences] <TempDebug> aAAAAAAAa");

	AddToReference('PlayerScripts', 	Reference.Player:WaitForChild("PlayerScripts"));
	AddToReference('LocalNetwork', 		Reference.PlayerScripts:WaitForChild("Network"));
	AddToReference('Network', 			game:GetService('ReplicatedStorage'):WaitForChild('Network'));
	AddToReference('GameNetwork', 		Reference.Network.Deathrun);
	AddToReference('GameState', 		Reference.GameNetwork.General.GameStateChanged);
	-- Frame References
	AddToReference('frameAchievement', 	Reference.InterfaceMain:WaitForChild("frameAchievement"));
	AddToReference('frameResults', 		Reference.InterfaceMain:WaitForChild("frameResults"));
	AddToReference('frameLeaderboard', 	Reference.InterfaceMain:WaitForChild("frameLeaderboard"));
	AddToReference('frameMessage', 		Reference.InterfaceMain:WaitForChild("frameMessage"));
	AddToReference('frameTransition', 	Reference.InterfaceMain:WaitForChild("frameTransition"));
	AddToReference('frameShowcase', 	Reference.InterfaceMain:WaitForChild("frameShowcase"));
	AddToReference('frameExperience', 	Reference.InterfaceMain:WaitForChild("frameExperience"));
	AddToReference('frameSpectate', 	Reference.InterfaceMain:WaitForChild("frameSpectate"));
	AddToReference('frameProgress', 	Reference.InterfaceMain:WaitForChild("frameProgress"));
	AddToReference('frameChat', 		Reference.InterfaceMain:WaitForChild("frameChat"));
	AddToReference('frameChatHolder', 	Reference.InterfaceMain:WaitForChild("frameChatHolder"));
	AddToReference('frameGift', 		Reference.InterfaceMain:WaitForChild("frameGift"));
	AddToReference('frameShop', 		Reference.InterfaceMain:WaitForChild("frameShop"));
	AddToReference('frameCountdown', 	Reference.InterfaceMain:WaitForChild("frameCountdown"));
	AddToReference('frameTimer', 		Reference.InterfaceMain:WaitForChild("frameTimer"));
	AddToReference('frameNeonShader', 	Reference.InterfaceMain:WaitForChild("frameNeonShader"));

	-- Buttons referenced seperately
	AddToReference('buttonShop', 		Reference.InterfaceMain:WaitForChild("buttonShop"));
	AddToReference('buttonSpectate', 	Reference.InterfaceMain:WaitForChild("buttonSpectate"));
	AddToReference('buttonMute', 		Reference.InterfaceMain:WaitForChild("buttonMute"));
	AddToReference('buttonConfig', 		Reference.InterfaceMain:WaitForChild("buttonConfig"));

	--AddToReference('KEYHERE', REFERENCEGOESHERE);
	--AddToReference('KEYHERE', REFERENCEGOESHERE);
	--AddToReference('KEYHERE', REFERENCEGOESHERE);
	--AddToReference('KEYHERE', REFERENCEGOESHERE);

	-- Add references to the environment to send back to the requiring script
	return function()
		for i,v in pairs(Reference) do
			getfenv(2)[i]			=	v;
		end
	end

