		local Class 						=	require(game:GetService('ServerScriptService').Framework.Ulilities.Class);	
		local PLAYERS 						=	{};

	--[[
        Functions
        ------------------------------------------------------------------------
	]]

		local function GetNotifaction(Type)
			if type(TYPES[Type]) == 'table' then
				return TYPES[Type];
			end

			return nil;
		end

		local function AddNotifaction(Player, Type)

			local Player 						=	(type(Player) == 'userdata' and Player.userId) or (type(Player) == 'number' and Player)
			local Playerdata 					=	PLAYERS[tostring(Player)];
			local myNotifaction 				=	GetNotifaction(Type);

			if type(Playerdata) == 'table' and type(myNotifaction) == 'table' then

				-- Print
				print('[Notifactions] New Notifaction for '..Player..'. Notifaction : '..Type)

				-- Add it to our Table
				table.insert(Playerdata, myNotifaction);
			end
		end	

		local function ClearNotifactions()

			-- Check or the Player is still in-game and and remove all Notifactions from the Player
			for Player,v in pairs(PLAYERS) do
				if type(game:GetService('Players'):GetPlayerByUserId(tonumber(Player))) == 'userdata' then
					PLAYERS[Player]			=	{};
				else
					PLAYERS[Player]			=	nil;
				end
			end

		end
	--[[
        Class
        ------------------------------------------------------------------------
    ]]

   	 	-- Create our new Class
		Notifactions 						=	Class('Notifactions');

		function Notifactions:initialize(Player)

			if type(PLAYERS[tostring(Player)]) == 'nil' then
				PLAYERS[tostring(Player)]	=	{};
			end

			self.Player 					=	Player;
		end

		function Notifactions:Get(Player)

			local Player 					=	type(Player) == 'number' and Player or self.Player;

			if type(PLAYERS[tostring(Player)]) == 'table' then
				print('Found a valid Notifactions table for Player !');
				return PLAYERS[tostring(Player)];
			end

			return nil;
		end

		game:GetService('ServerStorage').Network.Deathrun.Notifactions.RequestNotifaction.Event:connect(function(Player, Note)
			AddNotifaction(Player, Note);
		end)

		game:GetService('ServerStorage').Network.Deathrun.General.GameStateChanged.Event:connect(function(State)
			if State == 'Intermission' then
				ClearNotifactions();
			end
		end)

		return Notifactions;


