		local Teams 					=	game:GetService('Teams');
		local Players 					=	game:GetService('Players');
		local GameState 				=	'Waiting for Players';
		local Killer 					=	nil;
		local Listeners 				=	{};
		local Class 					=	require(game.ServerScriptService.Framework.Ulilities.Class);

    --[[
        Class
        ------------------------------------------------------------------------
    ]]
		print("<!!!> SPAWNMANAGER - START")
		-- Create our new Class
		local SpawnManager 					=	Class('SpawnManager');

		function SpawnManager:initialize(Player)
			self.Player 					=	type(Player) == 'userdata' and Player.userId or type(Player) == 'number' and Player;
			local Listener 					=	game:GetService('Players'):GetPlayerByUserId(self.Player);

			if type(Listener) == 'userdata' then
				Listeners[Listener]			=	false;
			end

			print('[Spawn Manager] New Manager created for '..self.Player);		
		end

		function SpawnManager:Respawn()
			assert(type(self.Player) == 'number', "[Spawn Manager] Could not find a valid Player !");

			local myPlayer	 				=	Players:GetPlayerByUserId(self.Player);
			local inGame 					=	false;

			if type(myPlayer) == 'userdata' then
				print('[Spawn Manager] We are reloading the Character of '..myPlayer.Name);

				if myPlayer.TeamColor == Teams.Killers.TeamColor or myPlayer.TeamColor == Teams.Runners.TeamColor then
					print("[Spawn Manager] Player is currently in-game !");

					if GameState == 'Ready' or GameState == 'Showcase' or GameState == 'Countdown' then

						-- Load our Character
						myPlayer:LoadCharacter();

						-- Wait until our Character is added
						local Character		= 	myPlayer.Character or myPlayer.CharacterAdded:wait();

						-- Lock him/her in Place
						local Humanoid		=	Character:WaitForChild('Humanoid');
						Humanoid.WalkSpeed	=	0;

					else

						-- Set in-game to true
						inGame 				=	true;

						if GameState ~= 'Playing' then
							inGame 			=	false;
						end

						if GameState == 'Playing' then
							if myPlayer.TeamColor == Teams.Runners.TeamColor then

								print('[Notifactions] Firing event for our Killer !');
								game:GetService('ServerStorage').Network.Deathrun.Notifactions.RequestNotifaction:Fire(Killer, 'Killed')
							end
						end

						-- Change TeamColor back to Lobby
						myPlayer.TeamColor	=	Teams.Lobby.TeamColor;

						-- Tell our game about it
						game:GetService('ServerStorage').Network.Deathrun['Spawn Manager'].CharacterDied:Fire(myPlayer, inGame);		

						coroutine.resume(coroutine.create(function()

							-- Wait 4 seconds
							wait(4)

							-- Reload our Character
							myPlayer:LoadCharacter();

							-- Tell our Client about it
							game:GetService('ReplicatedStorage').Network.Deathrun['Atmosphere'].SetClient:FireClient(myPlayer, 'Lobby');
							game:GetService('ReplicatedStorage').Network.Deathrun['Spawn Manager'].CharacterDied:FireClient(myPlayer, inGame);							
						end))		
					end
				else
					wait();
					myPlayer:LoadCharacter();
				end		
			else
				warn("[Spawn Manager] "..self.Player..' is not in-game anymore !');
			end
		end


		function SpawnManager:SetListener(boolean)
			assert(type(self.Player) == 'number', "[Spawn Manager] Could not find a valid Player !");

			local Playerobj				=	Players:GetPlayerByUserId(self.Player);

			if type(Playerobj) == 'userdata' then
				if type(boolean) == 'boolean' then
					Listeners[Playerobj]=	boolean;
				end
			end
		end

		function SpawnManager:Release(KillerWalkSpeed)

			for _,v in pairs(game:GetService('Players'):GetChildren()) do
				if v:IsA('Player') then

					local WalkSpeed 		=	v.TeamColor == Teams.Runners.TeamColor and 16 or KillerWalkSpeed;
					local Character			=	v.Character or v.CharacterAdded:wait();
					local Humanoid 			=	Character:WaitForChild('Humanoid');

					if v.TeamColor == Teams.Runners.TeamColor then
						Humanoid.WalkSpeed 	=	16;
					elseif v.TeamColor == Teams.Killers.TeamColor then
						Humanoid.WalkSpeed	=	KillerWalkSpeed;
					end
				end
			end
		end


    --[[
        Events
        ------------------------------------------------------------------------
    ]]

		-- Class functions
		game:GetService('ServerStorage').Network['Deathrun']['Spawn Manager'].RespawnCharacter.Event:connect(function(Player)
			local myManager 			=	SpawnManager:New(Player);
			myManager:Respawn();
		end)

		-- Game State
		game:GetService('ServerStorage').Network.Deathrun.General.GameStateChanged.Event:connect(function(State)
			GameState = State;
		end)

		game:GetService('ServerStorage').Network.Deathrun.General.KillerChanged.Event:connect(function(myKiller)			
			Killer 			=	myKiller;
		end)

		-- Network
		game:GetService('ReplicatedStorage').Network['Deathrun']['Spawn Manager'].LoadCharacter.OnServerEvent:connect(function(Player)
        	Player:LoadCharacter();
		end)

		game:GetService('Players').PlayerRemoving:connect(function(Plr)

			if type(Listeners[Plr]) == 'boolean' then
				Listeners[Plr]			=	nil;
			end
		end)

		game:GetService('Players').PlayerAdded:connect(function(Player)
			local Manager 				=	SpawnManager:New(Player);

			Player.CharacterAdded:connect(function(Character)
				print("[Spawn Manager] We are currently listing for "..Player.Name);
				local Humanoid 		=	Character:WaitForChild('Humanoid');

				Humanoid.Died:connect(function()
					print('[Spawn Manager] '..Player.Name..' has died !');

					local myListener=	type(Listeners[Player]) == 'boolean' and Listeners[Player] or false;

					if myListener then 
						print('[Spawn Manager] '..Player.Name..' will be respawned !');
						Manager:Respawn();
					else
						print("[Spawn Manager] "..Player.Name..' Listener has been disabled.');
					end
				end)
			end)
		end)


	--[[
        Return
        ------------------------------------------------------------------------
	]]
		print("<!!!> SPAWNMANAGER - RETURNING")
		return SpawnManager;

