   	 	-- Create our new Class
		Statistics 							=	Class('Statistics');

		function Statistics:initialize(Player)			
			self.Player 					=	(type(Player) == 'userdata' and Player.userId) or type(Player) == 'number' and Player;


			local myStorage 				=	Storage:New(Player);

			self['Coins']					=	myStorage:Get(Paths['Coins']);
			self['Gems']					=	myStorage:Get(Paths['Gems']);		
			self['Experience']				=	myStorage:Get(Paths['Experience']);

		end

		function Statistics:Add(Stat, Amount)
			assert(type(self.Player) == 'number', "[Statics] Player must be a valid number.");

			print('[Statistics] Adding request for '..self.Player);

			if type(self[Stat]) == 'number' and type(game.Players:GetPlayerByUserId(self.Player)) == 'userdata' then

				-- Push it to the Storage
				local myStorage 			=	Storage:New(self.Player);
				local Added 				=	myStorage:Add(Paths[Stat], Amount);

				-- Change our self with a live amount from the Database
				self[Stat] 					=	myStorage:Get(Paths[Stat]);

				print('[Statistics] New value from Server > Statistics : '..self[Stat]);

				-- Push out a Event to tell the Client about it
				local myPlayer 				=	game:GetService('Players'):GetPlayerByUserId(self.Player);

				if type(myPlayer) == 'userdata' then
					print('[Statistics] '..Stat..' : '..self[Stat]..' .');
					game:GetService('ReplicatedStorage').Network.Deathrun.Statistics.StatisticsChanged:FireClient(myPlayer, Stat, self[Stat]);
				end
			end
		end

		function Statistics:Deduct(Stat, Amount)
			assert(type(self.Player) == 'number', "[Statics] Player must be a valid number.");

			-- Get our Storage
			print('[Statistics] Deduct request for '..self.Player);

			if type(self[Stat]) == 'number' and type(game.Players:GetPlayerByUserId(self.Player)) == 'userdata' then

				-- Get a new connection with our Database
				local myStorage 			=	Storage:New(self.Player);

				-- Push it to our Storage
				local Old 					=	myStorage:Get(Paths[Stat]);
				local New 					=	Old - Amount;
				myStorage:Store(Paths[Stat], New);

				self.Stat 					=	New;

				-- Push out an event
				local myPlayer 				=	game:GetService('Players'):GetPlayerByUserId(self.Player);

				if type(myPlayer) == 'userdata' then

					game:GetService('ReplicatedStorage').Network.Deathrun.Statistics.StatisticsChanged:FireClient(myPlayer, Stat, New);

					print('Request has been fired.');
				end
			end
		end

		function Statistics:Balance(Stat, NotifyClient)
			assert(type(self.Player) == 'number', "[Statics] Player must be a valid number.");

			-- Get our value
			local myStorage 				=	Storage:New(self.Player);
			local Amount 					=	myStorage:Get(Paths[Stat]);

			-- Disconnect our Storage
			myStorage:Close();

			-- Fire it to our Client
			if type(NotifyClient) == 'boolean' and NotifyClient then

				local myPlayer 				=	game:GetService('Players'):GetPlayerByUserId(self.Player);

				if type(myPlayer) == 'userdata' then
					game:GetService('ReplicatedStorage').Network.Deathrun.Statistics.StatisticsChanged:FireClient(myPlayer, Stat, Amount);
				end
			end

			-- Return the value
			return Amount;
		end

		-- Events		
		function game.ReplicatedStorage.Network.Deathrun.Statistics.RequestStatistic.OnServerInvoke(Player, Stat)

			if type(Stat) == 'string' then
				local myStatistics	=	Statistics:New(Player.userId);
				return myStatistics:Balance(Stat)
			end

			return nil;
		end

		return Statistics;


