		local function GetHost(Character)
			local Host 							= Character:findFirstChild("ParticleHost");

			if Host == nil then
				wait(3)
				local P 						= Instance.new("Part")
				P.CanCollide 					= false
				P.Name 							= "ParticleHost";
				P.FormFactor 					= "Custom"
				P.Size 							= Vector3.new(.2, .2, .2)
				P.Transparency					= 1;

				local Motor 					= Instance.new("Motor6D")
				Motor.Name 						= "ParticleMotor";
				Motor.Part0 					= Character.Torso;
				Motor.Part1 					= P;

				P.Parent 						= Character;
				Motor.Parent 					= Character.Torso;

				return P;
			else

				return Host;
			end

		end

		local function Clear(Character)
			local Host 							=	GetHost(Character);
			local Torso 						=	Character.Torso;

			for _,v in pairs(Host:GetChildren()) do
				if v.ClassName == "ParticleEmitter" then
					v:Destroy();
				end
			end

			for _,v in pairs(Torso:GetChildren()) do
				if v.ClassName == "ParticleEmitter" then
					v:Destroy();
				end
			end
		end

		local function GetTarget(Character, Asset)
			local SpecialBrick 					=	false;

			if Asset:findFirstChild("Special") then
				SpecialBrick 					=	Asset.Special.Value;
			end

			if SpecialBrick then
				return GetHost(Character);
			end

			return Character.Torso;
		end

	--[[
