   	 	-- Create our new Class
		Trails 								=	Class('Trails');


		function Trails:Wear()
			assert(type(self.Player) == 'number', "[Trails] We need a valid player to wear");

			print('[Trails] New wear request from '..self.Player);

			local myTrail					=	TRAILS[self.Player];
			local Player 					=	game:GetService('Players'):GetPlayerByUserId(self.Player);

			if type(myTrail) == 'number' and type(Player) == 'userdata' then
				print('[Trails] We got a valid number..');

				if myTrail > 0 then
					if TRAILS_FOLDER:findFirstChild('item'..tostring(myTrail)) then
						print('[Trails] The Item has been found !');

						if type(Player) == 'userdata' then
							print('[Trails] Player has been found !');

							-- Equip it to the Player					
							local Character 	=	Player.Character or Player.CharacterAdded:wait();
							local Asset 		=	TRAILS_FOLDER['item'..tostring(myTrail)];
							local Host 			=	GetHost(Character);
							local Target 		=	GetTarget(Character, Asset);

							-- Remove any old Trails
							Clear(Character);

							-- Parent it to the Player						
							for _,v in pairs(Asset:GetChildren()) do
								if v.ClassName == 'ParticleEmitter' then
									v:Clone().Parent = Target;
								end
							end
						end
					end
				elseif myTrail == 0 then
					if type(Player) == 'userdata' then

						-- Character
						local Character 		=	Player.Character or Player.CharacterAdded:wait();

						if type(Character) == 'userdata' then
							Clear(Character);
						end
					end
				end

				game:GetService('ReplicatedStorage').Network.Market.ItemEquipped:FireClient(Player, 'Trails', tonumber("10"..myTrail));	
			end

		end

		function Trails:Equip(NewTrail)
			assert(type(self.Player) == 'number', "[Trails] We need a valid player to equip");

			local myTrail 					=	TRAILS[self.Player];
			local userStorage 				=	Storage:New(self.Player);

			print('[Trails] Equipping Trail '..NewTrail);

			if type(NewTrail) == 'number' then

				if NewTrail ~= myTrail then
					if TRAILS_FOLDER:findFirstChild('item'..tostring(NewTrail)) then
						print("[Trails] Found a valid Trail folder.");

						-- Change it locally 
						TRAILS[self.Player]		=	NewTrail;

						-- Store it to our Database
						userStorage:Store("Game>Character>Trail", NewTrail);

					end
				elseif NewTrail == myTrail then
					print("[Trails] De-equipping Trail..");

					-- Change it locally
					TRAILS[self.Player]			=	0;

					-- Store it to our Database
					userStorage:Store("Game>Character>Trail", 0);
				end
			end

			-- Close our Storage
			userStorage:Close();

			-- Wear the item
			self:Wear();
		end



		function Trails:Listen()
			assert(type(self.Player) == 'number', "[Trails] We need a valid player to equip");
			local Player 					=	game:GetService('Players'):GetPlayerByUserId(self.Player);

			if type(Player) == 'userdata' then

				print('[Trails] Listening for Input !');

				Player.CharacterAdded:connect(function(Char)
					wait();
					GetHost(Char);
					self:Wear();
				end)
			end
		end

		function Trails:initialize(Player)			
			self.Player 					=	(type(Player) == 'userdata' and Player.userId) or type(Player) == 'number' and Player;

			-- Get our Trail
			if type(TRAILS[self.Player]) == 'nil' then
				local myStorage 			=	Storage:New(self.Player);
				local Request 				=	myStorage:Get('Game>Character>Trail');

				print('[Storage] Request that got returned : '..type(Request));

				TRAILS[self.Player]			=	Request;

				-- Equip our Trail
				self:Listen();
			end
		end

		return Trails;


