	local function Clear()
		for Index,v in pairs(EVENTS) do
			if type(game:GetService('Players'):GetPlayerByUserId(Index)) == 'userdata' then
				EVENTS[Index]	=	{};
			else
				table.remove(EVENTS, Index);
			end
		end
