	local Events 					=	{};
	Events.__index 					=	Events;

	function Events:Add(Player, Type)
		local userId 				=	(type(Player) == 'userdata' and Player.userId) or type(Player) == 'number' and Player;
		local myEvent				=	type(TYPES[Type]) == 'table' and TYPES[Type] or nil;

		if type(userId) == 'number' and type(myEvent) == 'table' then

			if type(game:GetService('Players'):GetPlayerByUserId(userId)) == 'userdata' then

				if type(EVENTS[userId]) == 'nil' then
					CreatePlayer(userId);
				end			

				table.insert(EVENTS[userId], myEvent);
			end
		end
	end

	function Events:Bonus(Player, Type, Amount)
		local userId 				=	(type(Player) == 'userdata' and Player.userId) or type(Player) == 'number' and Player;
		local Type 					=	(type(Type) == 'string' and Type) or 'Coins';

		if type(userId) == 'number' then

			if type(game:GetService('Players'):GetPlayerByUserId(userId)) == 'userdata' then

				-- Add our Bonus event.
				local Found 		=	false;
				local Current 		=	Events:Get(Player);

				for _,v in pairs(Current) do
					if v.ID == 'Bonus' then
						Found 		=	true;
					end
				end

				if not Found then
					Events:Add(Player, 'Bonus');
				end

				-- Edit the stat that we need
				for _,v in pairs(EVENTS[userId]) do
					if v.ID == 'Bonus' then
						if type(v[Type]) == 'number' then
							v[Type]	=	Amount;
						end
					end
				end

			end
		end
	end

	function Events:Get(Player)
		local userId 				=	(type(Player) == 'userdata' and Player.userId) or type(Player) == 'number' and Player;

		return type(EVENTS[userId]) == 'table' and EVENTS[userId] or {};
	end



