	local REGISTERY 			=	{};
	local DATASTORES 			=	{};

	-- Services
	local DataStoreService 		=	game:GetService('DataStoreService');
	local HttpService 			=	game:GetService('HttpService');

	-- Other
	local READY 				=	false;

--[[
	Functions
	---------------------------------------------------------------------------
]]

	--[[
		General functions
		------------------------------------------------------------------------
		[!] Included a pcall() around the GetUser() method 'GetUserIdFromNameAsync', since it a web call ;(
	]]

		-- void Verify(other Value)
		-- @return boolean
		local function Verify(Value)

			if type(Value) == 'table' then
				local Encoded		=	HttpService:JSONEncode(Value);
				if string.len(Encoded) < 2 ^ 16 then

					return true
				end
			else
				return true;
			end

			return false;
		end

		-- void DeepCopy(table tb)
		-- @return table
		local function DeepCopy(tb)
			if type(tb) == 'table' then
				local new = {}
				for k, v in pairs(tb) do
					new[k] = DeepCopy(v)
				end
				return new
			else
				return tb
			end
		end

		-- void Init()
		-- @return boolean
		local function Init()

			if not READY then

				-- Create Database for our Users and the Registery
				DATABASE[USERS.Scope]		=	{};
				REGISTERY[USERS.Scope]		=	{};

				-- Create Database for our Server and the Registery
				DATABASE[SERVER.Scope]		=	{};
				REGISTERY[SERVER.Scope]		=	{};

				-- Create our Template for our User
				for _,v in pairs(TEMPLATE_LOCATIONS) do
					for _,j in pairs(v:GetChildren()) do
						if j.ClassName == 'ModuleScript' then
							USERS.Template[j.Name]		=	type(require(j)) ~= nil and require(j) or {};

							table.insert(USERS.Keys, j.Name);
						end
					end
				end

				-- Set Ready to true
				READY 						=	true;
			end

			return true;
		end

		-- void Split(string Path)
		-- @return table 
		local function Split(Path)
			local Result 	=	{}

			-- [!] Added support for numbers
			for Query in string.gmatch(Path, PATTERN) do
				if type(Query) == 'number' or type(tonumber(Query)) == 'number' then
					table.insert(Result, tonumber(Query))
				else
					table.insert(Result, Query)
				end
			end

			return Result
		end

		-- void GetUser(other Player)
		-- return int or nil
		local function GetUser(Player)

			-- Get our UserId based on the Type.
			if type(Player) == 'userdata' then
				if Player.ClassName == 'Player' then
					return Player.userId;
				end
			elseif type(Player) == 'string' then

				local Success, Plr	=	pcall(function() return game:GetService('Players'):GetUserIdFromNameAsync(Player) end);
				if Success then
					if type(Plr) == 'number' then
						return Plr;
					else
						warn("[Storage] We could not find an User with the name "..Player..' .');
					end
				else
					error("[Storage] Could not get the UserId of the Player. Error : "..Plr);
				end
			elseif type(Player) == 'number' then
				return Player;
			end

			-- Return
			return nil;
		end

