		-- void GetDataStore(string Name, string Scope, string Sort)
		-- @return userdata 'DataStore'
		local function GetDataStore(Name, Scope, Sort)

			if type(Sort) == 'string' then

				-- [!] Be sure that we aren't trying to get a Ordered Datastore for our user..
				if Sort:lower() == 'ordered' and Scope ~= USERS['Scope'] then
					local Success, DataStore 	=	pcall(function() return DataStoreService:GetOrderedDataStore(Name, (type(Scope == 'string' and Scope) or 'global')) end);
					if Success then
						return DataStore
					else
						warn("[Storage] Couldn't connect with ROBLOXs DataStoreService ! Error : "..DataStore.." .");
					end
				end
			end

			-- Execute the request, wrapped in pcall to ensure that we aren't erroring our Storage code.
			local Success, DataStore 	=	pcall(function() return DataStoreService:GetDataStore(Name, Scope or 'global') end);
			if Success then
				print('Succesfully got a new DataStore with type '..type(DataStore)..' .');
				return DataStore
			else
				warn("[Storage] Couldn't connect with ROBLOXs DataStoreService ! Error : "..DataStore);
			end

			return nil;
		end

		-- void SetValue(userdata DataStore, string Sort, string Key, other Value)
		-- @return boolean
		local function SetValue(DataStore, Sort, Key, Value)

			local Key 								=	tostring(Key);

			if DataStore ~= nil then

				if Sort:lower() == 'ordered' then

					-- [!] Ordered DataStores may only have Keys [Strings] and Values [Number] (Floats & Doubles)
					if type(Key) == 'string' and (type(Value) == 'number' or type(Value) == nil) then
						local Success, Message 		=	pcall(function() DataStore:SetAsync(Key, Value) end);
						if Success then
							return true;
						else
							error("[Storage] Couldnt set the value of key "..Key..'. \nMessage : '..Message, 0);
						end
					end

				else
					if type(Key) == 'string' then							

						local Success, Message 		=	pcall(function() DataStore:SetAsync(Key, Value) end);
						if Success then
							return true;
						else
							error("[Storage] Could not set the value of key "..Key.. ". \nMessage : "..Message, 0);
						end

						return true;
					end
				end

			end

			return false;
		end

		-- void GetValue(userdata DataStore, string Sort, tuple Arguments)
		-- @return other value or nil;
		local function GetValue(DataStore, Sort, Arguments)

			if type(DataStore) == 'userdata' then

				if Sort:lower() == 'ordered' then

					-- Unpack Arguments
					local Ascending 	=	type(Arguments.ascending) == 'boolean' and Arguments.ascending or true;
					local PageSize 		=	type(Arguments.PageSize) == 'number' and Arguments.PageSize or 10;
					local MinValue 		=	type(Arguments.MinValue) == 'number' and Arguments.MinValue or nil;
					local MaxValue 		=	type(Arguments.MaxValue) == 'number' and Arguments.MaxValue or nil;

					-- Verify Arguments
					if (PageSize > 100) then
						warn("[Storage] Sorry ! But we can only ask for a page element that is up to 100 elements !");
						PageSize 		=	100;
					end

					-- Return
					local Success, Res	=	pcall(function() return DataStore:GetSortedAsync(Ascending, PageSize, MinValue, MaxValue) end)
					if Success then
						return Res
					else
						error("[Storage] Could not get the value of the ordered DataStore !");
					end

				else

					-- Set our key
					local Key 			=	type(Arguments.Key) == 'string' and Arguments.Key or 'System';

					-- Return					
					local Success, Res	=	pcall(function() return DataStore:GetAsync(Key) end)
					if Success then
						return Res
					else
						error("[Storage] Could not get the value of the key "..Key.." .");
					end
				end
			else
				warn("[Storage] DataStore instance does not exist.");
			end

			return nil;
		end

		-- void UpdateValue(userdata DataStore, string Sort, string Key, other Value)
		-- @return boolean
		local function UpdateValue(DataStore, Sort, Key, Value)

			print('Update request for '..Key);

			local Key 								=	tostring(Key);

			if type(DataStore) == 'userdata' then

				if Sort:lower() == 'ordered' then

					-- [!] Ordered DataStores may only have Keys [Strings] and Values [Number] (Floats & Doubles)
					if type(Key) == 'string' and (type(Value) == 'number' or type(Value) == nil) then
						local Success, Message 		=	pcall(function() DataStore:UpdateAsync(Key, function(OldValue) return Value end) end);
						if Success then
							return true;
						else
							error("[Storage] Couldnt update the value of key "..Key..'. Message : '..Message, 0);
						end
					end

				else
					if type(Key) == 'string' then

						local Success, Message 		=	pcall(function() return DataStore:UpdateAsync(Key, function(OldValue) return Value end) end);

						if Success then
							return true;
						else
							error("[Storage] Couldnt update the value of key "..Key.. ". \nMessage : "..Message, 0);
						end

					end
				end
			else
				warn('[Storage] DataStore instance does not exist');
			end

			return false;
		end

