		-- void GetRegistery(string Scope, string Name)
		-- @return table or nil
		local function GetRegistery(Scope, Name)
			assert(type(Scope, Name) == 'string', "[Storage] 'GetRegistery()' needs valid arguments.");

			if type(REGISTERY[Scope]) == 'table' then
				if type(REGISTERY[Scope][Name]) == 'table' then
					return REGISTERY[Scope][Name];
				end
			end

			return nil;
		end

		-- void Register(other Player, string Sort)
		-- @return table or nil
		local function Register(Player, Sort)

			local Scope 			=	nil;
			local Name 				=	nil;
			local Sort 				=	type(Sort) == 'string' and Sort or 'Default';
			local Category 			=	'Server';

			-- Get our Category, Scope and Name
			local User 				=	GetUser(Player);
			if type(User) == 'number' then

				Scope 				=	USERS.Scope;
				Name 				=	USERS.Prefix..tostring(User);
				Sort				=	'Default';
				Category 			=	'User';

			else
				Scope 				=	SERVER.Scope;
				Name 				=	type(Player) == 'string' and Player;
			end

			-- Check or we are registered
			local REG 				=	GetRegistery(Scope, Name);
			if type(REG) == 'table' then
				return 				{
									['Scope']		=	Scope,
									['Name']		=	Name,
									['Sort']		=	Sort,
									['Category']	=	Category,
									['New']			=	false
				}
			else
				if Category == 'User' then
					print('[Storage] We are connecting User '..User..' to our Database !');

					-- Get a new DataStore
					print('Getting a new DataStore with '..Name..' and '..Scope);


					-- Create our new Database and Registery
					REGISTERY[Scope][Name]			=	{
														['Keys']		=	{};
					}
					DATABASE[Scope][Name]			=	{
														['System']		=	{};
					}



					-- Shortcuts
					local REG 						=	REGISTERY[Scope][Name];
					local DB 						=	DATABASE[Scope][Name];

					-- Create our new Keys variable
					local Keys 						=	USERS.Keys;

					-- Check or we can find a System entry on the ROBLOX Database.
					--[[
					local Result 					=	GetValue(
																DataStore,
																Sort,
																{
																['Key']		=	'System'
																}
					)]]


					-- Creer een Nieuwe database, connectie met ROBLOX en save het temporary in DATASTORES[Name]
					local DataStoreUser 			=	DataStoreService:GetDataStore(Name, Scope)
					DATASTORES[Name]				=	DataStoreUser;

					local Result 					=	GetValue(
																DataStoreUser,
																Sort,
																{
																['Key']		=	'System'
																}
					)

					-- Add System to our Database.
					if type(Result) == 'table' then
						print('Last time edited is on '..Result['Last edited']);
						print('Found valid data for our Player !');

						DB['System']				=	Result;
					else
						print('Type of Result is '..type(Result));

						DB['System']				=	{
														['Keys']			=	{},
														['Last edited']		=	os.time();
						}
					end

					-- Prepare keys.
					if type(Result) == 'table' then
						if type(Result.Keys) == 'table' then
							for _,v in pairs(Result.Keys) do
								local Found 		=	false;

								-- Check or we can find the key.
								for _,j in pairs(Keys) do
									if j == v then
										Found 		=	true;
										break;
									end
								end

								-- Add
								if not Found then
									table.insert(Keys, v);
								end
							end	
						end
					end

					DB['System']['Keys'] 			=	Keys;
					DB['System']['Last edited']		=	os.time();
					REG.Keys['System']				=	{
														['Time']		=	os.time(),
														['Changed']		=	true,
														['Locked']		=	false,
														['Save']		=	true
					}

					-- Catch all the results from the ROBLOX DataStore and add them to the Database
					for _,v in pairs(Keys) do

						-- Create a new Database field
						DB[v]						=	{};

						-- Fetch result from ROBLOX
						local Result 				=	GetValue(
																DataStoreUser,
																Sort,
																{
																['Key']	=	v;
																}

						)

						-- Add our new Result to the Database

						if type(Result) == 'nil' then

							-- Load Template data if it exist
							print('[Storage] Template found for '..v);
							DB[v]					=	type(USERS['Template'][v]) ~= nil and DeepCopy(USERS['Template'][v]) or {};	
						else
							if type(Result) == 'table' then
								DB[v]				=	DeepCopy(Result);
							else
								DB[v]				=	Result;
							end
						end

						-- Add it to our Registery
						REG.Keys[v]					=	{
														['Time']		=	os.time(),
														['Changed']		=	false,
														['Locked']		=	false,
														['Save']		=	true
						}
					end

					-- Add our Session field
					DB['Session']					=	{
														['userId']		=	User;
					}
					REG.Keys['Session']				=	{
														['Time']		=	os.time(),
														['Changed']		=	false,
														['Locked']		=	false,
														['Save']		=	false
					}

					-- Return the information
					return 				{
										['Scope']	=	Scope,
										['Name']	=	Name,
										['Sort']	=	Sort,
										['Category']=	Category,
										['New']		=	true;
					}

				else
					print('[Storage] Server type is currently not supported. Please ask Velibor for support !');
				end
			end

			return nil
		end

	--[[
		Data functions
