		-- void CollectKeys(Scope, Name)
		-- @return table
		local function CollectKeys(Scope, Name)
			local REG 					=	GetRegistery(Scope, Name);

			if type(REG) == 'table' then
				local Result 			=	{};

				for i,v in pairs(DATABASE[Scope][Name]) do
					table.insert(Result, i);
				end

				return Result;
			end

			return {};
		end

		-- void Store(string Path, string Sort, other Value)
		-- @return boolean
		local function Store(Path, Sort, Value)
			assert(type(Path, Sort) == 'string', "[Storage] 'Path' and 'Sort' must be valid arguments.");
			print('[Storage] Storage request.');				

			local SerializedPath		=	Split(Path);

			-- Get our Scope, Name, Key and the Others table
			if type(SerializedPath) == 'table' then

				-- Tables and our Count
				local Names 			=	{
											'Scope',
											'Name',
											'Key'
				}
				local Result 			=	{
											['Other']		=	{};
				}
				local Count 			=	0;

				-- Generate the Result
				for _,v in pairs(SerializedPath) do
					Count 				=	Count + 1;

					if type(Names[Count]) == 'string' then
						Result[Names[Count]] =	v;
					else
						table.insert(Result.Other, v);
					end
				end

				-- Get our Database
				local REG 				=	GetRegistery(Result.Scope, Result.Name);
				if type(REG) == 'table' then
					print('[Storage] Verified request. Registery exist !');

					if type(DATABASE[Result.Scope][Result.Name][Result.Key]) ~= nil then
						local Location 		=	DATABASE[Result.Scope][Result.Name][Result.Key];
						local Execute 		=	false;
						local Index 		=	nil;

						-- Check or we to investage further
						if #Result.Other > 0 then
							local Count 	=	0;
							for _,v in pairs(Result.Other) do
								Count 		=	Count + 1;

								if Count < #Result.Other then
									if type(Location[v]) == 'table' then
										Location	=	Location[v];
									else
										warn('[Storage] Could not fetch location !');									
										break;
									end
								elseif Count == #Result.Other then
									if type(Location[v]) ~= 'nil' then
										Index 		=	v;
										Execute 	=	true;
									end
								end
							end
						end

						-- Store our new data
						if Execute then 
							print('Execution has been done !');

							-- Store our value
							if type(Location[Index]) == 'table' then
								print('[Storage] Found a new table.');

								table.insert(Location[Index], Value);
							else
								Location[Index]		=	Value;
							end

							-- Update our Registery
							local KEY_REG 			=	REG.Keys[Result.Key];
							KEY_REG.Time 			=	os.time();
							KEY_REG.Changed 		=	true;

							print('Succesfully changed'..tostring(KEY_REG.Changed));

							-- Return true
							return true;
						end
					end
				end
			end

			return false;
		end		

		-- void Get(string Path, string Sort)
		-- @return nil or value
		local function Get(Path, Sort)
			assert(type(Path, Sort) == 'string', "[Storage] 'Path' and 'Sort' must be valid arguments.");

			local SerializedPath		=	Split(Path);

			-- Get our Scope, Name, Key and the Others table
			if type(SerializedPath) == 'table' then
				local Scope 			=	SerializedPath[1];
				local Name 				=	SerializedPath[2];
				local Key 				=	SerializedPath[3];

				print(Scope, Name, Key);

				local Other 			=	{};

				local Location 			=	type(DATABASE[Scope][Name][Key]) ~= 'nil' and DATABASE[Scope][Name][Key] or nil;

				print('Type location: '..type(Location));

				if type(Scope, Name, Key) == 'string' and type(Location) ~= 'nil' then
					if #SerializedPath > 3 then
						for _,v in pairs(SerializedPath) do
							if type(Location[v]) ~= 'nil' then
								Location	=	Location[v];
							end
						end
					end

					return Location;
				end
			end

			return nil;
		end

		-- void Push(string Scope, string Name, other Keys)
		-- @return boolean
		local function Push(Scope, Name, Sort, Keys)
			local REG 					=	GetRegistery(Scope, Name);
			local REQUEST 				=	{};
			local PUSHING 				=	{};

			if type(REG) == 'table' then

				-- Fetch our new DataStore
				local PushDataStore		=	type(DATASTORES[Name]) == 'userdata' and DATASTORES[Name] or nil;

				if type(PushDataStore) ~= 'userdata' then
					error("Could not fetch DataStore for a User that is still in progress.");
					return false;
				end

				-- Collect our request
				if type(Keys) == 'table' then
					for _,v in pairs(Keys) do
						if type(REG.Keys[v]) == 'table' then
							table.insert(REQUEST, v);
						end
					end
				elseif type(Keys) == 'string' then
					if Keys:lower() == 'all' then
						for i,v in pairs(REG.Keys) do
							table.insert(REQUEST, i);	
						end
					else
						if type(REG.Keys[Keys]) == 'table' then
							table.insert(REQUEST, Keys);
						end
					end
				end

				-- Verify the value and check or we need to push it.
				for _,v in pairs(REQUEST) do

					-- Print
					print('The next request is '..v);

					local REG_KEY		=	REG.Keys[v];
					local Value 		=	(type(DATABASE[Scope][Name][v]) ~= 'nil' and DATABASE[Scope][Name][v]) or nil;

					if type(Value) ~= 'nil' then
						if not REG_KEY.Locked and REG_KEY.Save then

							if REG_KEY.Changed and Verify(Value) then
								table.insert(PUSHING, v)
							else
								warn("[Storage] Key is not chnanged !");
							end
						else
							warn("[Storage] Key is locked or may not be saved");
						end
					end
				end

				-- Push the request to ROBLOX
				for _,v in pairs(PUSHING) do
					local REG_KEY 		=	REG.Keys[v];
					local Value 		=	(type(DATABASE[Scope][Name][v]) ~= 'nil' and DATABASE[Scope][Name][v]) or nil;

					if type(Value) ~= 'nil' then
						-- Lock our Key
						REG_KEY.Locked 		=	true;

						-- Update our value
						local Success 		=	UpdateValue(
															PushDataStore,
															Sort,
															v,
															Value
						)

						if Success then
							REG_KEY.Time 	=	os.time();
							REG_KEY.Changed	=	false;
						else
							warn("[Storage] We could not store "..v..' for '..Name);
						end

						-- Unlock our Key
						REG_KEY.Locked		=	false;
					end
				end

				return true;
			end

			return false;
		end

--[[
	Class
	---------------------------------------------------------------------------
]]

	-- Create our new Class
	Storage 							=	Class('Storage');

	function Storage:initialize(Argument, Sort)

		local Information 				=	Register(Argument, Sort)
		if type(Information) == 'table' then
			self.Scope 					=	Information.Scope;
			self.Name 					=	Information.Name;
			self.Category 				=	Information.Category;
			self.Sort 					=	Information.Sort;

			return true;			
		end

		return false;
	end

	function Storage:Store(Path, Value)
		assert(type(self.Scope, self.Name, self.Category, self.Sort) == 'string', "[Storage] 'self' is invalid.");
		assert(type(Path) == 'string' and type(Value) ~= 'nil', "[Storage] 'Path' must be a string value and 'Value' must be a value.");

		-- Create a new path
		local Path 						=	self.Scope..'>'..self.Name..'>'..Path;

		-- Execute request.			
		return Store(Path, self.Sort, Value);
	end

	function Storage:Get(Path)
		assert(type(self.Scope, self.Name, self.Category, self.Sort) == 'string', "[Storage] 'self' is invalid.");
		assert(type(Path) == 'string', "[Storage] 'Path' must be a string value.");

		-- Create a new path
		local Path 						=	self.Scope..'>'..self.Name..'>'..Path;

		-- Execute request
		return Get(Path, self.Sort);			
	end

	function Storage:Add(Path, Amount)
		assert(type(self.Scope, self.Name, self.Category, self.Sort) == 'string', "[Storage] 'self' is invalid.");
		assert(type(Path) == 'string' and type(Amount) == 'number', "[Storage] 'Path' must be a string value and 'Amount' must be a number !");

		-- Create a new path
		local Path 						=	self.Scope..'>'..self.Name..'>'..Path;

		-- Get the old result and add the new amount
		local OldValue 					=	Get(Path, self.Sort);

		if type(OldValue) == 'number' then

			local NewValue 				=	OldValue + Amount;
			return Store(Path, self.Sort, NewValue);
		end

		return false;
	end

	function Storage:Deduct(Path, Amount)
		assert(type(self.Scope, self.Name, self.Category, self.Sort) == 'string', "[Storage] 'self' is invalid.");
		assert(type(Path) == 'string' and type(Amount) == 'number', "[Storage] 'Path' must be a string value and 'Amount' must be a number !");

		-- Create a new path
		local Path 						=	self.Scope..'>'..self.Name..'>'..Path;

		-- Get the old result and add the new amount
		local OldValue 					=	Get(Path, self.Sort);

		if type(OldValue) == 'number' then

			local NewValue 				=	OldValue - Amount;
			return Store(Path, self.Sort, NewValue);
		end

		return false;
	end

	function Storage:Push(Keys)
		assert(type(self.Scope, self.Name, self.Category, self.Sort) == 'string', "[Storage] 'self' is invalid.");

		print(self.Scope, self.Name, self.Sort, Keys);
		return Push(self.Scope, self.Name, self.Sort, Keys);
	end

	function Storage:Close()
		assert(type(self.Scope, self.Name, self.Category, self.Sort) == 'string', "[Storage] 'self' is invalid.");

		self.Scope 						=	nil;
		self.Name 						=	nil;
		self.Category 					=	nil;
		self.Sort 						=	nil;
	end

	function Storage:Disconnect()
		assert(type(self.Scope, self.Name, self.Category, self.Sort) == 'string', "[Storage] 'self' is invalid.");

		-- Flush the entire Storage
		local Success 							=	self:Push('All');

		-- Remove our Registery and Database
		if Success then
			DATABASE[self.Scope][self.Name]		=	nil;
			REGISTERY[self.Scope][self.Name]	=	nil;
			DATASTORES[self.Name]				=	nil;

			-- Close down the Storage
			self:Close();

			print('Succesfully disconnected !');

			return true;
		end

		return false;
	end

