                -- Return the currency
				print('[Currency] for '..Currency..' : '..type(Current));
                return Current;
			end

			local function OrderProduct(Receipt)
				local AlreadyDone 				=	false;

				for _,v in pairs(DoneTransactions) do
					if v == Receipt.PurchaseId then
						AlreadyDone 			=	true;
						warn("[Transactions] Player already received there Product !");
						break;
					end
				end

				if not AlreadyDone then
					for _,v in pairs(STOCK) do
						if v.Meta.Category == 'Store' then
							if v.Meta['Product ID'] == Receipt.ProductId then
								if type(v.Meta.Currency) == 'string' and type(v.Meta.Amount) == 'number' then

									-- Set our Table
									table.insert(DoneTransactions, Receipt.PurchaseId);

									-- Add it to our Player
									local myStatistics	=	Statistics:New(Receipt.PlayerId);
									myStatistics:Add(v.Meta.Currency, v.Meta.Amount);

									print('[Transactions] We awared our items to the Player !');


									return true;
								end
							end
						end
					end
				end

				return false;
			end

            local function TransactionHandler(Receipt)

                	-- TO-DO : Find out how we are getting our Name for our Product from here..
					print('[Transactions] Got a new Transaction with '..Receipt.PurchaseId);

                    -- Create our Receipt for the Server, use the Doc below
                    local Receipt               =   {
                                                    ['Time']                =   os.time(),
													['PlayerId']			=	Receipt.PlayerId,
													['ProductId']			=	Receipt.ProductId,
                                                    ['PurchaseId']         	=   Receipt.PurchaseId,
                                                    ['Status']              =   'Bought';
                                                    ['Message']             =  	'Has succesfully bought our item'
                    };

					-- Store our Item 
                	local userStorage          	=   Storage:New(Receipt.PlayerId);
                	userStorage:Store('Transactions>Purchases', Receipt);

                    -- Order our Item by the ProductHandlers
					if OrderProduct(Receipt) then

						-- Push all the new Stats to the Client
						local myStats 			=	Statistics:New(Receipt.PlayerId);
						myStats:Balance('Gems', true);
						myStats:Balance('Coins', true);

						-- Push the Transactions index to ROBLOX.
						if userStorage:Push('Transactions') then
							return true;
						end
					end

					return false;
            end

			local function Equip(Customer, Category, ID)

				local Manager 					=	nil;

				if Category == 'Weapons' then
					Manager 					=	require(game:GetService('ServerScriptService').Project.Apps.Weapons.Weapons);

					game.ReplicatedStorage.Network.Deathrun.Weapons.UpdateSwordOnBack:Fire(Customer, ID)
					print("[Sword] has been equipped");

				elseif Category == 'Trails' then
					Manager 					=	require(game:GetService('ServerScriptService').Project.Apps.Trails.Trails);
				end

				if type(Manager) ~= 'nil' then

					-- Send a request to the Client with the new information
					game:GetService('ReplicatedStorage').Network.Market.ItemEquipped:FireClient(Customer, Category, ID);

					-- Equip our Item
					local myManager 			=	Manager:New(Customer);
					myManager:Equip(ID);

				end
			end

			local function IsTransactionAllowed(Customer, Product, Currency, inGame)

				if inGame then

					local userStorage 			=	Storage:New(Customer);

					-- Check our Inventory					
					local Inventory 			=	userStorage:Get('Game>Inventory>'..Product.Meta.Category) or {};

					for _,Item in pairs(Inventory) do

						if Item == Product.Meta.ID then
							print('[Transactions] Transaction denied. Player already owns that item !');

							Equip(Customer, Product.Meta.Category, Product.Meta.ID)							
							return false;
						end
					end

					-- Check our funds
					local Funds 				=	GetCurrency(Customer, Currency);
					if Funds >= Product.Price[Currency] then
						return true;
					else
						warn("[Transactions] Transaction denied. Player doesnt has enough funds");
						game:GetService('ReplicatedStorage').Network.Market.TransactionCompleted:FireClient(Customer, 'Insuffient funds', Product);
					end

				else

					if Product.Meta['Category'] == 'Boosts' then
						MarketPlace:PromptPurchase(Customer, Product.Meta['Gamepass ID'], false, 'Robux');
					else
						-- Prompt the Marketplace
						MarketPlace:PromptProductPurchase(Customer, Product.Meta['Product ID'],false, 'Robux');
					end
				end

				return false;
			end

            local function RequestTransaction(Customer, Product, Currency, inGame)

	            local Allowed                   =   IsTransactionAllowed(Customer, Product, Currency, inGame)

	            if Allowed then

    	            -- Deduct funds from the account
					local userStorage 			=	Storage:New(Customer.userId);
					if userStorage:Deduct('Game>Currencies>'..Currency, Product.Price[Currency]) then

						-- Close our connection to the Database.
						userStorage:Close();

						-- Prompt our PurchaseHandler
						OrderItem:Fire(Customer, Product.Meta.ID);
					end                        
				 end
	        end
