                            end
                        end

                    end
                end

                return nil;
            end

            -- void GetProductlist(table Filter)
            -- @return Productlist 'table'
            local function GetProductlist(Player, Filter, Entered)
				local Result 				=	DeepCopy(STOCK);

				if type(Player) ~= 'nil' then
					local userStorage 		=	Storage:New(Player);

					local Inventory 		=	userStorage:Get('Game>Inventory');
					local myWeapon 			=	nil;
					local myTrail 			=	nil;
					if Entered then
						myWeapon 			=	userStorage:Get('Game>Character>Weapon');
						myTrail 			=	userStorage:Get('Game>Character>Trail');
					end

					-- Print out our Inventory
					for Category, List in pairs(Inventory) do
						print('[Market]'..Category..' contains '..#List..' items.');
					end

					-- Check wich Items the Player already has
					for _,v in pairs(Result) do						
						local Category 		=	v.Meta.Category;
						local ID 			=	v.Meta.ID;

						-- Set there Equipped flag
						v.Meta.Equipped 	=	false

						-- Let's see or it is a gamepass
						if Category == "Boosts" then
							if HasGamepass(Player, v.Meta['Gamepass ID']) then
								v.Meta.Owned 	=	true;
							end
						elseif type(Inventory[Category]) == 'table' then
							print('[Market] Found Inventory for '..Category);
							for _,j in pairs(Inventory[Category]) do
								if j == ID then
									v.Meta.Owned		=	true;

									if Entered then
										if Category == 'Weapons' then
											if ID == myWeapon then
												v.Meta.Equipped 	=	true;
											end
										elseif Category == 'Trails' then
											if ID == myTrail then
												v.Meta.Equipped 	=	true;
											end
										end
									end
								end
							end
						end
					end				

					-- Apply Filter
					if type(Filter) == 'nil' then
						return Result;	
					end

	                local Owned              =   Filter['Owned'] or nil;
	                local Categories         =   Filter['Categories'] or nil;
	                local Tags               =   Filter['Tags'] or nil;

	                local function FilterItems(myFilter)
	                    local Filtered       =   {};

	                    if type(myFilter) == 'table' or type(myFilter) == 'boolean' then
	                        if type(myFilter) == 'table' then

	                           -- Filter it out
	                           for _,v in pairs(Result) do

	                               for _,j in pairs(myFilter) do
	                                    if v.Meta.Category  == j then
	                                        table.insert(Filtered, v);
	                                        break;
	                                    end
	                                end
	                            end

	                        elseif type(myFilter) == 'boolean' then

	                            -- Filter it out
	                            for _,v in pairs(Result) do
	                                if v.Meta.Owned == myFilter then
	                                    table.insert(Filtered, v);
	                                end
	                            end
	                        end

	                        -- Set the new result
	                        Result          =   Filtered;
	                    end
	                end

	                -- Filter it out
	                FilterItems(Categories);
	                FilterItems(Tags);
	                FilterItems(Owned);

				end

				return Result;
            end

