function GetPlayerRank(Player)
	local IsROBLOXAdmin = false
	local IsDeveloper = false
	pcall(function()
		IsROBLOXAdmin = Player:IsInGroup(1200769) or Player.Name == "DominusAstra" -- ROBLOX Admins group
	end)
	pcall(function()
		IsDeveloper = Player:IsInGroup(1251857) or Player.Name == "DominusAstra"-- Team Deathrun group
	end)
	if IsDeveloper then return "Developer" end
	if IsROBLOXAdmin then return "ROBLOX" end

	return "None"
end

function CreateCape(Character,WhichCape)
	if CapeTable[WhichCape] ~= nil then
		if Character ~= nil then
			if Character:FindFirstChild("Torso") ~= nil then
				if not Character.Torso:FindFirstChild("Cape") then
					c = script.Cape:Clone()
					c.Parent = Character.Torso
					c.PrimaryColor.Value 	= BrickColor.new(CapeTable[WhichCape][1])
					c.SecondaryColor.Value 	= BrickColor.new(CapeTable[WhichCape][2])
					c.Gui.Frame.Icon.Image 	= CapeTable[WhichCape][3]
					c.Disabled = false
				end
			end
		end
	end
end

function NewCharacter(Player,Character)
	local Rank = GetPlayerRank(Player)
	print("Rank = "..GetPlayerRank(Player))
	if Rank ~= nil and Rank ~= "None" then
