			local function HasGamepass(Player, ID)
				local Owns 		=	false;
				local Player 	=	(type(Player) == 'number' and game:GetService('Players'):GetPlayerByUserId(Player) or type(Player) == 'userdata' and Player) or nil;

				if type(Player) == 'userdata' and type(ID) == 'number' then
