					local Success, Res = pcall(function() return game:GetService("MarketplaceService"):PlayerOwnsAsset(Player, ID) end)
					if Success then
						print("Player "..Player.Name.." has gamepass with ID "..ID);
						Owns 	=	Res;
					else
						error(Res);
					end
				end

				return Owns;
			end

		--[[
			Connect
			-------------------------------------------------
		]]

			local function ConnectPlayer(Player)

				local Index 	=	tostring(Player.userId);

				-- Create our data record of the Player
				PLAYERS[Index]	=	{
									['Session']	=	nil,
									['userId']	=	Player.userId,
									['Name']	=	Player.Name,
									['Chance']	=	0
				}

				-- Create an boolean value in the Player regarding AFK
				local AFK 		=	Instance.new('BoolValue', Player);
				AFK.Name 		=	"Online";
				AFK.Value 		=	false;
			end

		--[[
			System
			-------------------------------------------------
		]]

			-- void Init()
			-- @return boolean
			local function Init()
			end

			local function Clear()

				for Index,v in pairs(PLAYERS) do
					if type(game:GetService('Players'):GetPlayerByUserId(v.userId)) == 'userdata' then
						print('Hello there '..v.Name);
					else
						PLAYERS[Index]		=	nil;
					end
				end
			end

			-- void GatherPlaying()
			-- @return table
			local function GatherPlaying()
				local myPlayers 			=	{};

				-- Gather the Players that are either in our Killers or Runners Team
				for _,v in pairs(Players:GetChildren()) do
					if (v.TeamColor == Teams.Runners.TeamColor or v.TeamColor == Teams.Killers.TeamColor) then
						local Online 		=	true;

						if v:findFirstChild("Online") then
							Online 			=	v.Online.Value;
						end

						if Online then
							table.insert(myPlayers, v);
						end
					end
				end

				-- return our Players
				return myPlayers
			end

			-- void GetPlayersReady()
			-- @return table
			local function GetPlayersReady()
				local Result 				=	{};

				for _,v in pairs(PLAYERS) do
					local Online 			=	true;
					local Player 			=	game:GetService('Players'):GetPlayerByUserId(v.userId);

					if type(Player) == 'userdata' then
						if Player:findFirstChild("Online") then
							Online 			=	Player.Online.Value;
