						print("Player :"..Player.Name..". Online : "..tostring(Online));

						if Online == true then
							table.insert(Result, Player);
						end
					end
				end

				return Result;
			end

			-- void CreateSession(userdata Plr)
			local function CreateSession(Plr)

				local Index 				=	tostring(Plr.userId);
				if type(PLAYERS[Index]) == 'table' then
					PLAYERS[Index].Session 	=	{
												['Time']	=	os.time(),
												['Team']	=	(Plr.TeamColor == 'Runners' and game.Teams.Runners.TeamColor) or game.Teams.Killers.TeamColor;
												['Died'	]	=	false,
												['Won']		=	false
					}
				end
			end

			-- void 

		--[[
			Table
			-------------------------------------------------
		]]

			-- void Sort(table Tbl, void f)
			-- @return table
			local function Sort(Tbl, f)
				local keys 			=	{};

				for key in pairs(Tbl) do
					table.insert(keys, key)
				end

				table.sort(keys, function(a, b) return f(Tbl[a], Tbl[b]) end)

				return keys
			end

			-- void Copy(table Tbl)
			-- @return table
			local function Copy(Tbl)
				local new 		=	{};

				for k,v in pairs(Tbl) do
					new[k]		=	Copy(v);
				end

				return new;
			end

		--[[
			Game - System
			-------------------------------------------------
		]]

			-- void SendMessage(string State, table Arguments, table Plrs)
			local function SendMessage(State, Arguments, Plrs)

				-- Let's set our Ping
				Ping 					=	os.time();

				-- Set our game State
				GAME.State 				=	State;

				-- Create our delivery
				local Delivery 			=	{
											['State']			=	State;
											['Arguments']		=	type(Arguments) == 'table' and Arguments or {}
				}

				-- Get our Receivers
				local Receivers 		=	type(Plrs) == 'table' and {} or Players:GetChildren();

				if type(Plrs) == 'table' then
					for _,v in pairs(Plrs) do
						local Plr 		=	Players:GetPlayerByUserId(v.userId);

						if type(Plr) == 'userdata' then
							table.insert(Receivers, Plr);
						end
					end
				end

				-- Send our message
				if type(Plrs) == 'table' then
					for _,v in pairs(Receivers) do
						Message:FireClient(v, Delivery);
					end
				else
					Message:FireAllClients(Delivery);
				end
			end

			-- void GetKillers(int Amount)
			-- @return table
			local function GetKillers(Amount)

				print(Amount);

				-- Table that holds our possible killers
				local myKillers 			=	{};
				local Killers 				=	{};

				-- Get our Players and add them to the Killers list
				for _,v in pairs(GetPlayersReady()) do
					local Chance_MOD	 	=	HasGamepass(v.userId, CHANCE_ID);
					local Chance_ADD 		=	1;
					local userId 			=	tostring(v.userId);
					local Playerdata 		=	PLAYERS[tostring(v.userId)];


					if Chance_MOD then
						warn("Player has our gamepass !")
						Chance_ADD 			=	Chance_ADD + CHANCE_INCREASE;
					end

					Playerdata.Chance 		=	Playerdata.Chance + Chance_ADD;

					myKillers[userId]		=	Playerdata.Chance;

					warn("[Killer Picker] "..userId..' has '..Playerdata.Chance);
				end

				-- Sort our table
				local Sorted 				=	Sort(myKillers, function(a, b) return a > b end);

				-- Get our Killers
				for _,userId in pairs(Sorted) do

					local userId 			=	tonumber(userId);

					if (#Killers < Amount) then

						-- Remove the chance by the Player
						PLAYERS[tostring(userId)].Chance 			=	0;

						warn('The chance is :'..PLAYERS[tostring(userId)].Chance)

						local Player 		=	Players:GetPlayerByUserId(userId);
						if type(Player) == 'userdata' then

							PLAYERS[tostring(Player.userId)].Chance 	=	0;

							table.insert(Killers, Player);
						end
					end

				end

				-- return our Killers
				print('Amount of Killers picked : '..#Killers);
				return Killers;
			end

			-- void GetMap()
			-- @return userdata
			local function GetMap()

				-- void StreamMap(userdata Map)
				local function StreamMap(Map)

					if STREAMING_ENABLED then
						-- We need to think of a proper way to stream the Asset to the Workspace

					else

						local myMap 		=	Map:Clone();
						myMap.Parent 		=	Workspace;
						myMap.Name 			=	'CurrentMap';
					end
				end

				-- void ClearMaps()
				local function ClearMaps()
					for _,v in pairs(game:GetService('Workspace'):GetChildren()) do
						if v.Name == 'CurrentMap' and v.ClassName == 'Model' then
							v:Destroy();
						end
					end
				end

				local Wait 						=	false;

				-- Clear all the maps that are currently in Workspace
				ClearMaps();

				-- Check or we have a map in the last round and don't allow that one to enter the pool		
				if type(GAME.Map) == 'userdata' then

					--[[for Index,v in pairs(game:GetService('ServerStorage').Assets.Maps:GetChildren()) do
