							table.insert(Maps, v);
						end
					end
					]]
				else
					Wait 						=	true;
				end


				-- Pick our new map
				local function CreateList()

					-- Seed it					
					--math.randomseed(os.time() - math.random(1, os.time()));

					-- Create a new list based on our Maps
					local Maps = game:GetService('ServerStorage').Assets.Maps:GetChildren();
	    			assert( Maps, "shuffleTable() expected a table, got nil" )
	    			local iterations = #Maps;
	    			local j;

	    			for i = iterations, 2, -1 do
	        			j = math.random(1, i);
	        			Maps[i], Maps[j] = Maps[j], Maps[i]
	    			end

					MapRow 						=	Maps;
				end

				local function PickMap()

					if type(MapRow) == 'table' then
						if #MapRow >= 1 then
							local PickedMap		=	MapRow[1];
							table.remove(MapRow, 1);

							return PickedMap;
						else
							CreateList();
							return PickMap();
						end
					end

				end

				GAME.Map 						=	PickMap();


				-- Stream our map to the Workspace
				StreamMap(GAME.Map);

				-- Wait up to 10 seconds so that the map is fully loaded.
				if Wait then
					wait(10);
				end

				-- return our new map
				return GAME.Map;
			end

			-- void GetMode()
			-- @return table
			local function GetMode()

				return {};
			end

			-- void Heartbeat()
			local function Heartbeat(State)

				local Seconds 		=	STATES[State];
				local Success 		=	false;

				print('[Deathrun] New heartbeat started with '..Seconds);
				coroutine.resume(coroutine.create(function()

					for i = Seconds, 0, -1 do
						game:GetService('ReplicatedStorage').Network.Deathrun.General.Heartbeat:FireAllClients(i, State)

						if i <= 0 then
							Success	=	true;
						end

						wait(1);
					end
				end))

				repeat wait() until Success 
				return true;
			end


		--[[
			Game
			-------------------------------------------------
		]]

			-- void Start()
			-- Starts a new Deathrun game
			local function Start()

				print('Request to start a new game with '..#Players:GetChildren()..' Players.');

				-- Check or the game is currently busy and or we have the required amount of Players.
				print(PLAYING);

				if not PLAYING and #GetPlayersReady() >= MIN_PLAYERS then
					print('[Deathrun] We are starting a new round with '..#Players:GetChildren()..' Players.');

					-- Set our Playing flag to true
					PLAYING 		=	true;

					-- Send our Preparing message
					SendMessage(
								'Preparing'
					)

					-- Get our new map and mode
					if type(GAME.Map) == 'nil' then
						GetMap();
						GAME.Mode 	=	GetMode();
					end

					-- Send our Intermission message
					SendMessage(
								'Intermission', 
								{
								['Time']		=	STATES.Intermission;
								}
					)

					-- Set our server correctly to Intermission
					game.ServerStorage.Network.Deathrun.General.GameStateChanged:Fire('Intermission')

					-- Heartbeat to our Clients
					if Heartbeat('Intermission') then

						-- Get all Players that can join the match
						-- [!] We have to come up with something else here..
						local myPlayers 	=	GetPlayersReady();

						-- Pick our Killers
						local KillerAmount	=	GAME.Map.Meta.MapMaxKillers.MinValue;
						local Killers 		=	GetKillers(KillerAmount);
						GAME.Killers 		=	Killers;


						-- Give all Players the correct TeamColor
						for _,v in pairs(myPlayers) do

							local function isKiller(Plr)
								for _,j in pairs(Killers) do
									if j.userId == Plr.userId then
										return true;
									end
								end

								return false;
							end

							if isKiller(v) then
								v.TeamColor 	=	Teams.Killers.TeamColor;
							else
								v.TeamColor 	=	Teams.Runners.TeamColor;
							end

							-- Create our Player session
							CreateSession(v);
						end

						-- Send our Showcase message
						SendMessage(
									'Showcase',
									{
									['Name']	=	GAME.Map.Name,
									['Creator']	=	GAME.Map.Meta.MapCreator.Value;
									},
									GatherPlaying()
						)

						-- Set our Game time limit
						GAME['Time']			=	GAME.Map.Meta.MapTimeLimit.MaxValue;

						-- INTERMISSION LOAD DELAY
						-- Teleport clients after this delay
						wait(.7)

						-- Load all our Players inside the map
						for _,v in pairs(GatherPlaying()) do

							Connection 			= v.CharacterAdded:connect(function(Char)

								if Char:findFirstChild('Humanoid') then
									Char.Humanoid.WalkSpeed 	=	0;

									Connection:disconnect();
								end
							end)

							-- Reload our Character
							v:LoadCharacter();

							-- Change the Lighting
							game.ReplicatedStorage.Network.Deathrun.Atmosphere.SetClient:FireClient(v, 'Map');
						end

						-- Wait until the Showcase is complete
						wait(STATES.Showcase);

						-- Send our Countdown Heartbeat to the Server
						if Heartbeat('Countdown') then

							-- Release all our Players
							for _,v in pairs(GatherPlaying()) do

								if type(v.Character) == 'userdata' then
									if v.Character:findFirstChild('Humanoid') then
										local Hum 					=	v.Character.Humanoid;

										if v.TeamColor == Teams.Killers.TeamColor then
											Hum.WalkSpeed 			=	WALKSPEEDS.Killers;
										else
											Hum.WalkSpeed 			=	WALKSPEEDS.Runners;
										end

									end
								end
							end

							-- Send the Playing message to our Client
							SendMessage(
										'Playing'
							)

							-- Set our Start time
							GAME.Start 							=	os.time();

							-- Release our hand
							local MotivatorHand 				=	game:GetService('ServerStorage').Assets.Gameplay.Hand:Clone();
							MotivatorHand.Parent 				=	game.Workspace.CurrentMap;
							MotivatorHand:SetNetworkOwner();
						end
					end
				end

			end

			local function PostStats(userId)
				assert(type(userId) == 'number', "[Post Stats] We only accept valid userIds");

				local user 										=	game:GetService('Players'):GetPlayerByUserId(userId);
				if type(user) == 'userdata' then

					-- Create a new Storage
					local userStorage 							=	Storage:New(userId);

					-- Get our Stats
					local Package								=	{
																	['Coins'] 		=	userStorage:Get('Game>Currencies>Coins') or 0;
																	['Gems']		=	userStorage:Get('Game>Currencies>Gems') or 0;
																	['Experience'] 	=	userStorage:Get('Game>Character>Experience') or 0;
					}

					-- Post it to our Client
					for Stat,Amount in pairs(Package) do
						game:GetService('ReplicatedStorage').Network.Deathrun.Statistics.StatisticsChanged:FireClient(user, Stat, Amount);
					end
				end
			end

			-- void End(
			-- Ends the current game of Deathrun
			local function End(Mode, Winners, Losers)

				-- Set the end time of the game
				GAME['End']				=	os.time();

				warn("[Deathrun] The mode is "..Mode);

				-- Send the Game over message to all clients.
				SendMessage(
							'Game over'
				);

				-- Give all Players that are still in-game a 'Particapte' event
				for _,v in pairs(PLAYERS) do
					if type(v.Session) == 'table' then
						Events:Add(v.userId, 'Participate');

						if not v.Session.Died then
							Events:Add(v.userId, 'Winner');
							v.Session.Won		=	true;
							v.Session.Time 		=	os.time();
						end
					end
				end

				if Mode == 'Time reached' then
				else

					if not Mode == 'Tie' then
					end
				end

				local function Report()

					local function Collect()
						local Duration 		=	GAME.End - GAME.Start;
						local Total			=	Duration * APG;
						local PlayerPoints	=	{};

						print("[Deathrun] The game has finished in "..Duration..' seconds.');
						print('[Deathrun] A total of '..Total..' could be rewared to our Players.');

						for userId,v in pairs(PLAYERS) do

							if type(v.Session) == 'table' and type(game:GetService('Players'):GetPlayerByUserId(userId)) == 'userdata' then

								-- Create our Points
								local Points 	=	0;

								-- Get the Players session
								local Session 	=	v.Session;
								local userId 	=	tonumber(userId);

								-- Get our Notifactions
								local myEvents 	=	Events:Get(userId) or {};

								-- Award our Coins / Experience
								local myStorage =	Storage:New(userId);

								-- Temporary variables
								local XP_REWARD	=	0;
								local XP_BONUS	=	0;
								local C_REWARD	=	0;
								local C_BONUS	=	0;

								for _,v in pairs(myEvents) do

									-- Award our experience and coins to the Player
									if type(v.Experience) == 'number' then
										XP_REWARD 		=	XP_REWARD + v.Experience;
									end

									if type(v.Coins) == 'number' then
										C_REWARD 		=	C_REWARD + v.Coins;
									end

									-- Add our Points
									if type(v.Points) == 'number' then
										Points 			=	Points + v.Points;
									end
								end

								-- Calculate our bonus
								local XP_MOD, COINS_MOD =	HasGamepass(userId, EXP_ID), HasGamepass(userId, COINS_ID);
								if XP_MOD or COINS_MOD then
									warn("Player has our gamepass for double XP and Double Coins.");
									XP_BONUS 			=	(XP_MOD and XP_REWARD * EXP_INCREASE) or 0;
									C_BONUS 			=	(COINS_MOD and C_REWARD * COINS_INCREASE) or 0;

									print(XP_BONUS);
									print(C_BONUS);

									-- Add our Event
									Events:Bonus(userId, 'Experience', math.ceil(XP_BONUS));
									Events:Bonus(userId, 'Coins', math.ceil(C_BONUS));
								end

								-- Give our Player the necassary reward
								coroutine.resume(coroutine.create(function()
									myStorage:Add("Game>Currencies>Coins", C_REWARD + C_BONUS);
									myStorage:Add("Game>Character>Experience", XP_REWARD + XP_BONUS);
								end))

								-- Award our Time points to the Player
								Points 					=	Points + (Duration * (Session.Time / Total));

								-- Add it in our table
								PlayerPoints[userId]	=	Points;
							end
						end

						return PlayerPoints;
					end

					local function FetchLeaderboard(Points)

						-- Create our leaderboard
						local Leaderboard 	=	{};

						-- Filter out any records that are from the Killers
						local Index 			=	1;
						local Reference 		=	{};

						local function isKiller(Plr)
							for _,j in pairs(GAME.Killers) do
								if j.userId == Plr then
									return true;
								end
							end

							return false;
						end

						for userId,Amount in pairs(Points) do

							if not isKiller(userId) then
								Reference[userId]	=	Amount;
							end

						end

						-- Sort our Leaderboard out
						local Sorted 			=	Sort(Reference, function(a,b) return a > b end);

						for Place,User in pairs(Sorted) do
							print('[Leaderboard] '..User..' has place #'..Place);

							-- Pack our data
							local myEvents		=	Events:Get(User) or {};
							local myStorage		=	Storage:New(User);

							local SessionCoins	=	0;
							local SessionXP 	=	0;
							local CurrentEXP 	=	myStorage:Get('Game>Character>Experience') or 0;
							local Label 		=	'Ran for 00:00';

							-- Get our Session Coins and Experience
							for _,v in pairs(myEvents) do
								local ID 		=	v.ID;

								-- Get our coins and experience
								if type(v.Coins) == 'number' then
									SessionCoins =	SessionCoins + v.Coins;
								end

								if type(v.Experience) == 'number' then
									SessionXP 	=	SessionXP + v.Experience;
								end

								-- Get our label
								if ID == 'Teleported' then
									Label 		=	'Reached the end';
								elseif ID == 'Slayer' then
									Label 		=	'Killed the killer';
									break;
								end
							end	

							-- Create our ran label
							if Label == 'Ran for 00:00' then
								local Playerdata 	=	type(PLAYERS[tostring(User)]) == 'table' and PLAYERS[tostring(User)] or {};
								local Session 		=	type(Playerdata.Session) == 'table' and Playerdata.Session or nil;

								print('[Deathrun] Label type : '..type(Session));

								if type(Session) == 'table' then
									local Time 		=	Session.Time - GAME['Start'];
									local Minutes	=	0;
									local Seconds 	=	Time;

									while Seconds >= 60 do
										Minutes 	=	Minutes + 1;
										Seconds 	=	Seconds - 60;
									end

									if Seconds >= 10 then
										Label 		=	'Ran for 0'..Minutes..':'..Seconds;
									else
										Label 		=	'Ran for 0'..Minutes..':0'..Seconds;
									end
								end
							end

							-- Put it inside our Leaderboard
							local Playerdata 		=	type(PLAYERS[tostring(User)]) == 'table' and PLAYERS[tostring(User)];
							table.insert(Leaderboard, {Playerdata.Name, CurrentEXP, SessionXP, SessionCoins, Label})
						end

						return Leaderboard;
					end

					local function FetchRound()

						local function isKiller(Plr)

							for _,j in pairs(GAME.Killers) do
								if j.userId == Plr then
									return true;
								end
							end

							return false
						end

						local function GetKiller()
							for _,v in pairs(PLAYERS) do
								if isKiller(v.userId) then
									return v;
								end
							end

							return nil;
						end

						local function GetVictims()
							local Amount 		=	0;
							local Total 		=	0;

							for _,v in pairs(PLAYERS) do
								if type(v.Session) == 'table' then
									if type(v.Session.Team) == 'userdata' then
										if v.Session.Team == game.Teams.Runners.TeamColor then
											Total 		=	Total + 1;

											if v.Session.Died then
												Amount 	=	Amount + 1;
											end
										end
									end
								end
							end

							return Total, Amount;
						end

						local myKiller 			=	GetKiller();
						local Victims, Killed	=	GetVictims();

						-- Get our experience 
						local myStorage 		=	Storage:New(myKiller.userId) or nil;
						local result 			=	myStorage:Get('Game>Character>Experience');
						local userXP 			=	0;

						if type(result) == 'number' then
							userXP 				=	result;
						end

						-- Get our event data
						local myEvents 			=	Events:Get(myKiller.userId) or {};
						local Coins 			=	0;
						local Experience 		=	0;

						for _,v in pairs(myEvents) do
							if type(v.Coins) == 'number' then
								Coins 			=	Coins + v.Coins;
							end

							if type(v.Experience) == 'number' then
								Experience 		=	Experience + v.Experience;
							end
						end

						-- Package our data
						return 		{
									['Killer']	=	{
													['Name']		=	myKiller.Name,
													['userId']		=	myKiller.userId,
													['Current XP']	=	userXP + Experience,
													['XP']			=	Experience,
													['Coins']		=	Coins,
													['Level']		=	0
									},
									['General']	=	{
													['TotalRunners']	=	Victims,
													['KilledRunners']	=	Killed
									}
						}
					end

					local function Results()

						local myResults 		=	{};

						for _,v in pairs(PLAYERS) do

							local Coins 		=	0;
							local Experience 	=	0;
							local myEvents 		=	Events:Get(v.userId);
							local Won 			=	false;

							-- Gather our Coins and Experience
							for _,v in pairs(myEvents) do

								if type(v.Coins) == 'number' then
									Coins 		=	Coins + v.Coins;
								end

								if type(v.Experience) == 'number' then
									Experience 	=	Experience + v.Experience;
								end
							end

							-- Check or the Player has won
							if type(v.Session) == 'table' then
								if type(v.Session.Won) == 'boolean' then
									Won 		=	v.Session.Won;
								end
							end

							myResults[tostring(v.userId)]	=	{
																['Coins']			=	Coins,
																['Experience']		=	Experience,
																['Notifactions']	=	myEvents,
																['Won']				=	Won
							}
						end

						return myResults;
					end

					-- Collect and fetch our data
					local Points 				=	Collect();
					local Results 				=	Results();
					local Leaderboard 			=	FetchLeaderboard(Points);
					local Round 				=	FetchRound();

					-- Reset all our Players that are still in-game !
					for _,Player in pairs(GatherPlaying()) do
						print('[Deathrun]'..Player.Name..' will be reset now.');

						coroutine.resume(coroutine.create(function()

							Player.TeamColor 	=	game.Teams.Lobby.TeamColor;

							wait(4);

							Player:LoadCharacter();
							game:GetService('ReplicatedStorage').Network.Deathrun['Atmosphere'].SetClient:FireClient(Player, 'Lobby');

						end))
					end

					-- Fire the Results for each Player
					for _,v in pairs(game:GetService('Players'):GetChildren()) do

						-- Fire our Stats change for each Player
						PostStats(v.userId);

						-- Send a message to our Client with the round information
						SendMessage(
								   'Results',
								   {
								   [1]	=	type(Results[tostring(v.userId)]) == 'table' and Results[tostring(v.userId)] or {},
								   [2]	=	Round,
								   [3]	=	Leaderboard
								   },
								   {v}
						)
					end

					return true;
				end

				-- Fetch our Leaderboard and make our game report.
				if Report() then
					wait(5);

					-- [!] Change our experience levels for each user

					-- Clear Players
					Clear();

					-- Create our next map
					local newMap 		=	GetMap();
					GAME.Map 			=	newMap;

					-- Wait until our Results are finished
					wait(STATES.Results - 5);

					-- Change the State of the game to Preparing
					GAME.State 			=	'Preparing';

					-- Set Playing flag to false
					PLAYING 			=	false;

					-- Start a new round
					Start();
				end
			end

			-- void Check()
			-- Checks or the game should be ended
			local function Check()

				if PLAYING and GAME.State == 'Playing' then

					local Killers 		=	{};
					local Runners		=	{};

					for _,v in pairs(GatherPlaying()) do
						if v.TeamColor == Teams.Killers.TeamColor then
							table.insert(Killers, v);
						else
							table.insert(Runners, v);
						end
					end

					print('[Game] Players checking.. Runners : '..#Runners..' Killers : '..#Runners);

					if #Killers == 0 and #Runners == 0 then
						End('Tie', Killers, Runners);
					elseif #Killers == 0 then
						End('Runners have won', Runners, Killers);
					elseif #Runners == 0 then
						End('Killers have won', Killers, Runners);
					end

				end
			end

			local function Died(Player)
				print('[Deathrun] '..Player.Name..' has died !');

				if type(PLAYERS[tostring(Player.userId)]) == 'table' then
					PLAYERS[tostring(Player.userId)].Session.Died 	=	true;
					PLAYERS[tostring(Player.userId)].Session.Time	=	os.time();

					local function GetKiller()
						for _,v in pairs(game:GetService('Players'):GetChildren()) do
							if v.TeamColor == game.Teams.Killers.TeamColor then
								return v;
							end
						end
					end

					-- Add a Killed event for our Killer
					local myKiller 				=	GetKiller();

					if type(myKiller) == 'userdata' then
						Events:Add(myKiller.userId, 'Killed');
					end
				end

				coroutine.resume(coroutine.create(function()

					-- Set the Team Color to Lobby
					Player.TeamColor 			=	game.Teams.Lobby.TeamColor;

					wait(4);

					-- Reload our Character
					if game:GetService('Players'):GetPlayerByUserId(Player.userId) then

						-- Load our Character
						Player:LoadCharacter();

						-- Tell our client about it
						game:GetService('ReplicatedStorage').Network.Deathrun['Atmosphere'].SetClient:FireClient(Player, 'Lobby');
						game:GetService('ReplicatedStorage').Network.Deathrun['Spawn Manager'].CharacterDied:FireClient(Player, true);	
					end
				end))

				wait();

				-- Check our the game should be ended.
				Check();

			end

			coroutine.resume(coroutine.create(function()
				while true do

					if PLAYING and GAME.State == 'Playing' then

						-- Check our the game time is over
						if type(GAME.Start, GAME.Time) == 'number' then

							if GAME['Start'] + GAME['Time'] <= os.time() then
								End('Time reached');
							end

							game:GetService('ReplicatedStorage').Network.Deathrun.General.Heartbeat:FireAllClients(math.floor((GAME['Start'] + GAME['Time']) -  os.time()),GAME.State)
						end

						-- Check our the Players are still correct
						Check();
					else
						Start();
					end

					-- Ping timeout
					if Ping + PING_TIMEOUT <= os.time() then
						warn("[Game] PING TIMEOUT ! Restarting game..");
						PLAYING 		=	false;
						Ping 			=	os.time();
						Start();
					end

					-- Wait one second
					wait(1);
				end

			end))

