		local function PlayerConnected(Player)

			-- Create our Playerdata
			ConnectPlayer(Player);

			-- Equip our Trail
			local myTrail 							=	Trail:New(Player.userId);
			myTrail:Listen();

			game:GetService('ReplicatedStorage').Network.Deathrun['Atmosphere'].SetClient:FireClient(Player, 'Lobby');
			game:GetService('ReplicatedStorage').Network.Deathrun['Spawn Manager'].CharacterDied:FireClient(Player, true);

			-- Event to check or our Players Character has been added to the game
			Player.CharacterAdded:connect(function(Character)

				-- Special for the use-case that Players reset during the States 'Showcase' and 'Countdown'
				if Player.TeamColor == Teams.Killers.TeamColor or Player.TeamColor == Teams.Runners.TeamColor then
					if GAME.State == 'Countdown' or GAME.State == 'Showcase' then
						local function Mute(Char)
							coroutine.resume(coroutine.create(function()
								local Humanoid 		=	Char:WaitForChild('Humanoid');

								-- Mute there WalkSpeed
								Humanoid.WalkSpeed 	=	0;

							end))
						end

						Mute(Character);
					end
				end

				-- Died event
				Character:WaitForChild('Humanoid');

				Character.Humanoid.Died:connect(function()

					if Player.TeamColor == Teams.Killers.TeamColor or Player.TeamColor == Teams.Runners.TeamColor then						

						if GAME.State == 'Countdown' or GAME.State == 'Showcase' then
							Player:LoadCharacter();
						elseif GAME.State == 'Playing' then

							-- Fire our Died function to correct handle this use-case
							Died(Player);
						end

					else

						-- Player has died in the Lobby, reload there Character
						Player:LoadCharacter();
					end

				end)

			end)

		end

		local function PlayerDisconnected(Player)

			-- Print
			print('[System] Player '..Player.Name..' has left the game.')

			-- Check or the game should be ended
			Check();

			-- Flush our Storage
			local myStorage 			=	Storage:New(Player.userId);
			myStorage:Disconnect();
		end

		for _,v in pairs(Players:GetChildren()) do
			PlayerConnected(v)
		end

		-- Events for Players
		Players.PlayerAdded:connect(function(Player)
			PlayerConnected(Player)
		end)

		Players.ChildRemoved:connect(function(Player)
			if Player:IsA('Player') then
				PlayerDisconnected(Player);
			end
		end)

