function PlaceGeyser(AtCFrame)
	local Hole = CreatePart()
	Hole.Size = Vector3.new(4, .4, 4)
	Hole.BrickColor = BrickColor.new("Reddish brown")
	Hole.Material = "Pebble"
	Hole.CanCollide = false
	Hole.CFrame = AtCFrame
	Hole.Parent = script.Parent
