	Cyl.Scale = Vector3.new(1.4, 1, 1.4)
	wait(.5)
	local W = CreatePart()
	W.Anchored = false
	W.CanCollide = false
	local Cyl = Instance.new("CylinderMesh", W)
	local BP = Instance.new("BodyPosition", W)
	Cyl.Scale = Vector3.new(1.1, 1, 1.1)
	W.Size = Vector3.new(4, 11, 4)
	W.BrickColor = BrickColor.new("Pastel light blue")
	W.Material = "Granite"
	W.Transparency = .3
	W.CFrame = AtCFrame*CFrame.new(0, -1-W.Size.Y/2, 0)
	BP.position = (AtCFrame*CFrame.new(0, W.Size.Y/2, 0)).p
	BP.maxForce = Vector3.new(99999, 99999, 99999)
	W.Touched:connect(function(hit)
		if hit.Parent:findFirstChild("Humanoid")~=nil then
			if game.Players:GetPlayerFromCharacter(hit.Parent)~=nil then
				local Plr = game.Players:GetPlayerFromCharacter(hit.Parent)
				if Plr.TeamColor.Name == game:GetService("Teams").Runners.TeamColor.Name then
					hit.Parent.Humanoid.Health = 0
				end
			end
		end
	end)
	local PE = Instance.new("ParticleEmitter", W)
	PE.Texture = "http://www.roblox.com/asset/?id=275333833"
	PE.RotSpeed = NumberRange.new(-50, 50)
	PE.Speed = NumberRange.new(6)
	PE.Rate = 15
	PE.Lifetime = NumberRange.new(5)
	PE.Acceleration = Vector3.new(0, -16, 0)
	PE.Size = NumberSequence.new(1.8)
	W.Parent = script.Parent
	wait(3)
	W:Destroy()
	Hole:Destroy()
end

