		local Part = GeyserGround:GetChildren()[math.random(1, #GeyserGround:GetChildren())]
		local CF = Part.CFrame*CFrame.new(((Part.Size.X-4)*(math.random()-.5)), 0, ((Part.Size.Z-4)*(math.random()-.5)))
			*CFrame.Angles(0, math.pi*2*math.random(), 0)
		PlaceGeyser(CF)
	else
		print(2)
		local ChosenBlock = PossibleBlocks[math.random(1, #PossibleBlocks)]
		local Front = (ChosenBlock.CFrame*CFrame.new(0, 0, -ChosenBlock.Velocity.magnitude/2)).p
		local Start = Front+Vector3.new(0, 15, 0)
		local End = Front+Vector3.new(0, -40, 0)
		local Line = Ray.new(Start, (End-Start).unit*55)
		local HitBlock, HitPos = game.workspace:FindPartOnRayWithIgnoreList(Line, GetPlayerModels(), false)
