						Ignores[#Ignores+1] = B[c]
					end
				end
				local HitBlock, HitPos = game.workspace:FindPartOnRayWithIgnoreList(Line, Ignores, false)
				if HitBlock~=nil then
					if HitBlock.Parent.Name == "SnowEmitters" then
						if P[i].Character:findFirstChild("Humanoid")~=nil then
							P[i].Character:findFirstChild("Humanoid").Health = 0
