	for e = 1, #F do
		if F[e].Character then
			List[#List+1] = F[e].Character
		end
	end
	return List
end

function CheckKillOnBlock(BlockName)
	local P = game.Players:GetPlayers()
	for i = 1, #P do
		if P[i].TeamColor.Name == game:GetService("Teams").Runners.TeamColor.Name then
			if P[i].Character then
				if P[i].Character:findFirstChild("Torso")~=nil then
					local Start = P[i].Character:findFirstChild("Torso").Position
					local End = Start+Vector3.new(0, -30, 0)
					local Line = Ray.new(Start, (End-Start).unit*30)
					local HitBlock, HitPos = game.workspace:FindPartOnRayWithIgnoreList(Line, GetPlayerModels(), false)
					if HitBlock~=nil then
						if HitBlock.Name == BlockName then
							if P[i].Character:findFirstChild("Humanoid")~=nil then
								game.ReplicatedStorage.Network.Deathrun.Effects.RequestEffect:FireClient(P[i], "Ragdoll", 3.5)
								local BF = Instance.new("BodyForce")
								BF.Force = HitBlock.CFrame.lookVector*500
								BF.Parent = P[i].Character.Torso
								wait(2)
								if BF~=nil then
									BF:Destroy()
								end
							end
						end
					end
				end
			end
		end
	end
end

function Trigger()
	coroutine.resume(
		coroutine.create(
			function()
				script.Parent.Fan1.Particles.ParticleEmitter.Enabled = true
				script.Parent.Fan2.Particles.ParticleEmitter.Enabled = true
				local AddCF = 0
				local RotTime = 5
				local StartTime = tick()
				while StartTime+RotTime > tick() or AddCF > 0 do
					wait()
					if AddCF < math.pi/7 and StartTime+RotTime > tick() then
						AddCF = AddCF+math.pi/64
					end
					if AddCF > 0 and StartTime+RotTime <= tick() then
						AddCF = AddCF-math.pi/64
						if AddCF < 0 then
							AddCF = 0
						end
					end
					script.Parent.Fan1.Fans.CFrame = script.Parent.Fan1.Fans.CFrame*CFrame.Angles(0, AddCF, 0)
					script.Parent.Fan2.Fans.CFrame = script.Parent.Fan2.Fans.CFrame*CFrame.Angles(0, AddCF, 0)
				end
				script.Parent.Fan1.Particles.ParticleEmitter.Enabled = false
				script.Parent.Fan2.Particles.ParticleEmitter.Enabled = false
			end
		)
	)
	wait(.4)
	for i = 1, 10 do
		wait(.5)
		coroutine.resume(
			coroutine.create(
				function()
					CheckKillOnBlock("CheckPart")
				end
			)
		)
	end
end

