function Shoot(Eye)	
	for k = 1, 5 do
		wait(math.random(1, 10) / 10 *.25)
		local P = GetPlayerModels()
		local Possible = {}
		for i = 1, #P do
			local T = P[i]:findFirstChild("HumanoidRootPart")
			local Start, End = T.Position, T.Position+Vector3.new(0, -30, 0)
			local Line = Ray.new(Start, (End-Start).unit*30)
			local HitBlock, HitPos = game.workspace:FindPartOnRayWithIgnoreList(Line, P, false)
			if HitBlock~=nil then
				if HitBlock.Name == "HitBox" then
					local TargetPos = Vector3.new(HitPos.X, HitPos.Y, HitPos.Z)
					Possible[#Possible+1] = TargetPos
				end
			end
		end
		if #Possible > 0 then
			local TargetPos 	= Possible[math.random(1, #Possible)]
			local M 			= script.Parent.Missle:clone()
			Eye:SetPrimaryPartCFrame(CFrame.new(Eye.Main.Position, Vector3.new(TargetPos.X, Eye.Main.Position.Y, TargetPos.Z)));

			--[[
			Turret.Sentry.Top:SetPrimaryPartCFrame(CFrame.new(Eye.Sentry.Top.Main.Position,
				Vector3.new(TargetPos.X, Turret.Sentry.Top.Main.Position.Y, TargetPos.Z)))
			Turret.Sentry.Top.Cannon.CFrame = CFrame.new(Turret.Sentry.Top.Cannon.Position, TargetPos)*CFrame.Angles(-math.pi/2, 0, 0)
			]]			

			M:SetPrimaryPartCFrame(Eye.Eye.CFrame)
			M:SetPrimaryPartCFrame(CFrame.new(M.PrimaryPart.Position, TargetPos)*CFrame.Angles(math.pi/2, 0, 0))


			local StartTime = tick()
			local EndTime = tick()+(M.PrimaryPart.Position-TargetPos).magnitude/Speed;
			local Dir = (TargetPos-Eye.Main.Position).unit
			M.Parent = game.workspace
			coroutine.resume(
				coroutine.create(
					function()
						repeat
							wait()
							local Result = Eye.Main.Position+(Dir*Speed*(tick()-StartTime))
							M:SetPrimaryPartCFrame(CFrame.new(Result.X, Result.Y, Result.Z))
							M:SetPrimaryPartCFrame(CFrame.new(M.PrimaryPart.Position, TargetPos)*CFrame.Angles(math.pi/2, 0, 0))
						until tick() >= EndTime
						M:Destroy()
						local Exp = Instance.new("Explosion")
						Exp.Position = TargetPos
						Exp.Parent = game.Workspace
						wait(1)
						if Exp.Parent~=nil then
							Exp:Destroy()
						end
					end
				)
			)
		end
	end
end

