	local function GetTorso(Model)
		for _,p in pairs(Model:GetChildren()) do
			if p.ClassName == "Part" then
				if p.Size == Vector3.new(2, 2, 1) then
					return p;
				end
			end
		end

		return nil;
	end

	local function GetCharacters()
		local Characters 	=	{};

		for _,v in pairs(game:GetService('Players'):GetChildren()) do
			if v.TeamColor == game.Teams.Runners.TeamColor then
				local Char 	=	(type(v.Character) == 'userdata' and v.Character) or nil;

				if type(Char) == 'userdata' then
					local h =	Char:findFirstChild('Humanoid');

					if type(h) == 'userdata' then
						if h.Health > 0 then
							table.insert(Characters, Char);
						end
					end
				end
			end
		end

		return Characters;
	end

	local function CreateHand(CFrame)
		local Hand 			=	Instance.new("Part");
		Hand.Size 			=	Vector3.new(1, 2, 1);
		Hand.Name 			=	'SkeletonHand';
		Hand.Anchored 		=	true;

		local Mesh 			=	Instance.new("SpecialMesh");
		Mesh.MeshType 		=	Enum.MeshType.FileMesh;
		Mesh.Parent 		=	Hand;
		Mesh.Name 			=	'Mesh';
		Mesh.Scale 			=	Vector3.new(2, 2, 2);
		Mesh.TextureId 		=	"http://www.roblox.com/asset/?id=11827934";
		Mesh.VertexColor 	=	Vector3.new(1, 1, 1);

		-- Create the hole that appears when the hand will be coming out

		-- Return
		Hand.Parent 		=	script.Parent.Hands;
		return Hand;

	end

	function CreatePart()
		local Block = Instance.new("Part")
		Block.Anchored = true
		Block.FormFactor = "Custom"
		Block.TopSurface = "Smooth"
		Block.BottomSurface = "Smooth"
		return Block
	end

	local function Place(CF)

		print('Placing hand !');
		CF				=	CF * CFrame.new(0, 10, 0);

		local Hole 		=	CreatePart();

		print('Hello...');
		Hole.Size 		=	Vector3.new(.4, .4, .4);
		Hole.BrickColor	=	BrickColor.new("Reddish brown");
