		wait(.4);

		-- Create our Collision mask
		local W 		=	CreatePart();
		W.Name 			=	'Hand'
		W.Anchored 		=	false;
		W.CanCollide 	=	false;
		W.Size 			=	Vector3.new(1, 2, 1);
		W.BrickColor 	=	BrickColor.new("Pastel light blue");
		W.Material 		=	"Granite";
		W.Transparency 	=	0;
		W.CFrame 		=	CFrame.new(CF.x, CF.y, CF.z) * CFrame.Angles(-179, 0, 0);

		-- Insert the hand mesh
		local Mesh 		=	Instance.new("SpecialMesh", W);
		Mesh.MeshId 	=	"http://www.roblox.com/asset/?id=36780032";
		Mesh.MeshType	=	Enum.MeshType.FileMesh;
		Mesh.Scale 		=	Vector3.new(2, 2, 2);
		Mesh.TextureId	=	"http://www.roblox.com/asset/?id=11827934";
		W.Parent 		=	script.Parent.Hands;


		-- Create our BodyPosition
		local BP 		=	Instance.new("BodyPosition", W);
		BP.position 	=	(CF * CFrame.new(0, W.Size.Y/2, 0)).p;
		BP.maxForce 	=	Vector3.new(99999, 99999, 99999);

		W.Touched:connect(function(Hit)
			if Hit.Parent:findFirstChild("Humanoid") ~= nil then
				if game.Players:GetPlayerFromCharacter(Hit.Parent) ~= nil then
					local Plr 	=	game.Players:GetPlayerFromCharacter(Hit.Parent);
					if Plr.TeamColor.Name == game:GetService('Teams').Runners.TeamColor.Name then
						Hit.Parent.Humanoid.Health = 0;
					end
				end
			end
		end)

		print("Succesfully placed hand !");
		wait(5);

		BP.Position 	=	(CF * CFrame.new(0, -W.Size.Y/.85, 0)).p;

		wait(5);
		W:Destroy();
		Hole:Destroy();
	end

	local function PrepareHand()

		print('Preparing hand !');
		local Ground 	=	script.Parent.TrapGround;
		local Targets 	=	GetCharacters();
		print("Targets : "..#Targets);
		local Possible 	=	{};

		for _,v in pairs(Targets) do
			local Goal		=	GetTorso(v);

			if type(Goal) ~= nil then
				local Front	=	(Goal.CFrame * CFrame.new(0, 0, -Goal.Velocity.magnitude/2)).p;
				local Start =	Front + Vector3.new(0, 15, 0);
				local End 	=	Front + Vector3.new(0, -40, 0);
				local Line 	=	Ray.new(Start, (End - Start).unit*55);
				local B,P	=	game.Workspace:FindPartOnRayWithIgnoreList(Line, GetCharacters(), false);
				if B ~= nil then
					if B.Parent.Name == "TrapGround" then
						table.insert(Possible, Goal);
					end
				end
			end
		end

		local CF 			=	nil;

		if #Possible <= 0 then
			print("Not anymore possible !");
			local Part 		=	Ground:GetChildren()[math.random(1, #Ground:GetChildren())];
			CF 				=	Part.CFrame * CFrame.new(((Part.Size.X-4)*(math.random()-.5)), 0, ((Part.Size.Z-4)*(math.random()-.5))) * CFrame.Angles(0, math.pi*2*math.random(), 0)
		else
			print("Picking a brick for this target");
			local Picked	=	Possible[math.random(1, #Possible)];
			local Front 	=	Picked.CFrame * CFrame.new(0, 0, -Picked.Velocity.magnitude/2).p;
			local Start 	=	Front + Vector3.new(0, 15, 0);
			local End 		=	Front + Vector3.new(0, 60, 0);
			local Line 		=	Ray.new(Start, (End-Start).unit * 55);
			local B,P 		=	game.Workspace:FindPartOnRayWithIgnoreList(Line, GetCharacters(), false);
			if type(B) ~= nil then
