					CF 		=	CFrame.new(P.X, P.Y, P.Z) * CFrame.Angles(0, math.pi * 2 * math.random(), 0);
				end
			end
		end

		Place(CF);
	end

	function Trigger()

		print("Trap has been triggered !");
		for i = 1, Amount do
			coroutine.resume(coroutine.create(function() PrepareHand() end))
			wait(.35);
		end
	end

