--[[
	Skeleton Hand trap
	---------------------------------------------------------------
	Description : When the Players enter the Skeletonhand area and they don't jump out of the way, they will
	be taken with the hand back in the ground.
]]


--[[
	Settings
	---------------------------------------------------------------
]]

	local Cooldown 				=	12;
	local Amount 				=	20;
	local Regen 				=	true;

--[[
	Variables
	---------------------------------------------------------------
]]

	local Used 					=	false;

--[[
	Functions
	---------------------------------------------------------------
]]


	local function GetTorso(Model)
		for _,p in pairs(Model:GetChildren()) do
			if p.ClassName == "Part" then
				if p.Size == Vector3.new(2, 2, 1) then
					return p;
				end
			end
		end

		return nil;
	end

	local function GetCharacters()
		local Characters 	=	{};

		for _,v in pairs(game:GetService('Players'):GetChildren()) do
			if v.TeamColor == game.Teams.Runners.TeamColor then
				local Char 	=	(type(v.Character) == 'userdata' and v.Character) or nil;

				if type(Char) == 'userdata' then
					local h =	Char:findFirstChild('Humanoid');

					if type(h) == 'userdata' then
						if h.Health > 0 then
							table.insert(Characters, Char);
						end
					end
				end
			end
		end

		return Characters;
	end

	local function CreateHand(CFrame)
		local Hand 			=	Instance.new("Part");
		Hand.Size 			=	Vector3.new(1, 2, 1);
		Hand.Name 			=	'SkeletonHand';
		Hand.Anchored 		=	true;

		local Mesh 			=	Instance.new("SpecialMesh");
		Mesh.MeshType 		=	Enum.MeshType.FileMesh;
		Mesh.Parent 		=	Hand;
		Mesh.Name 			=	'Mesh';
		Mesh.Scale 			=	Vector3.new(2, 2, 2);
		Mesh.TextureId 		=	"http://www.roblox.com/asset/?id=11827934";
		Mesh.VertexColor 	=	Vector3.new(1, 1, 1);

		-- Create the hole that appears when the hand will be coming out

		-- Return
		Hand.Parent 		=	script.Parent.Hands;
		return Hand;

	end

	function CreatePart()
		local Block = Instance.new("Part")
		Block.Anchored = true
		Block.FormFactor = "Custom"
		Block.TopSurface = "Smooth"
		Block.BottomSurface = "Smooth"
		return Block
	end

	local function Place(CF)

		print('Placing hand !');
		CF				=	CF * CFrame.new(0, 0, 0);

		local Hole 		=	CreatePart();

		print('Hello...');
		Hole.Size 		=	Vector3.new(.4, .4, .4);
		Hole.BrickColor	=	BrickColor.new("Reddish brown");
		Hole.CanCollide =	false;
		Hole.Name 		=	'Hole'
		Hole.Material 	=	"Pebble";	
		Hole.CFrame 	=	CF;
		Hole.Parent 	=	script.Parent.Hands;

		print("Succesfully put Hole !");

		-- Add a Cylinder to it
		local Cyl 		=	Instance.new("CylinderMesh", Hole);
		Cyl.Scale 		=	Vector3.new(1.4, 1, 1.4);
		wait(.4);

		-- Create our Collision mask
		local W 		=	CreatePart();
		W.Name 			=	'Hand'
		W.Anchored 		=	false;
		W.CanCollide 	=	false;
		W.Size 			=	Vector3.new(1, 2, 1);
		W.BrickColor 	=	BrickColor.new("Pastel light blue");
		W.Material 		=	"Granite";
		W.Transparency 	=	0;
		W.CFrame 		=	CFrame.new(CF.x, CF.y, CF.z) * CFrame.Angles(-179, 0, 0);

		-- Insert the hand mesh
		local Mesh 		=	Instance.new("SpecialMesh", W);
		Mesh.MeshId 	=	"http://www.roblox.com/asset/?id=36780032";
		Mesh.MeshType	=	Enum.MeshType.FileMesh;
		Mesh.Scale 		=	Vector3.new(2, 2, 2);
		Mesh.TextureId	=	"http://www.roblox.com/asset/?id=11827934";
		W.Parent 		=	script.Parent.Hands;


		-- Create our BodyPosition
		local BP 		=	Instance.new("BodyPosition", W);
		BP.position 	=	(CF * CFrame.new(0, W.Size.Y/2, 0)).p;
		BP.maxForce 	=	Vector3.new(99999, 99999, 99999);

		W.Touched:connect(function(Hit)
			if Hit.Parent:findFirstChild("Humanoid") ~= nil then
				if game.Players:GetPlayerFromCharacter(Hit.Parent) ~= nil then
					local Plr 	=	game.Players:GetPlayerFromCharacter(Hit.Parent);
					if Plr.TeamColor.Name == game:GetService('Teams').Runners.TeamColor.Name then
						Hit.Parent.Humanoid.Health = 0;
					end
				end
			end
		end)

		print("Succesfully placed hand !");
		wait(5);

		BP.Position 	=	(CF * CFrame.new(0, -W.Size.Y/.85, 0)).p;

		wait(2);
		W:Destroy();
		Hole:Destroy();
	end

	local function PrepareHand()

		print('Preparing hand !');
		local Ground 	=	script.Parent.TrapGround;
		local Targets 	=	GetCharacters();
		print("Targets : "..#Targets);
		local Possible 	=	{};

		for _,v in pairs(Targets) do
			local Goal		=	GetTorso(v);

			if type(Goal) ~= nil then
				local Front	=	(Goal.CFrame * CFrame.new(0, 0, -Goal.Velocity.magnitude/2)).p;
				local Start =	Front + Vector3.new(0, 15, 0);
				local End 	=	Front + Vector3.new(0, -40, 0);
				local Line 	=	Ray.new(Start, (End - Start).unit*55);
				local B,P	=	game.Workspace:FindPartOnRayWithIgnoreList(Line, GetCharacters(), false);
				if B ~= nil then
					if B.Parent.Name == "TrapGround" then
						table.insert(Possible, Goal);
					end
				end
			end
		end

		local CF 			=	nil;

		if #Possible <= 0 then
			print("Not anymore possible !");
			local Part 		=	Ground:GetChildren()[math.random(1, #Ground:GetChildren())];
			CF 				=	Part.CFrame * CFrame.new(((Part.Size.X-4)*(math.random()-.5)), 0, ((Part.Size.Z-4)*(math.random()-.5))) * CFrame.Angles(0, math.pi*2*math.random(), 0)
		else
			print("Picking a brick for this target");
			local Picked	=	Possible[math.random(1, #Possible)];
			local Front 	=	Picked.CFrame * CFrame.new(0, 0, -Picked.Velocity.magnitude/2).p;
			local Start 	=	Front + Vector3.new(0, 15, 0);
			local End 		=	Front + Vector3.new(0, 60, 0);
			local Line 		=	Ray.new(Start, (End-Start).unit * 55);
			local B,P 		=	game.Workspace:FindPartOnRayWithIgnoreList(Line, GetCharacters(), false);
			if type(B) ~= nil then
				if B.Name == "GroundTrap" then
					CF 		=	CFrame.new(P.X, P.Y, P.Z) * CFrame.Angles(0, math.pi * 2 * math.random(), 0);
				end
			end
		end

		Place(CF);
	end

	function Trigger()

		print("Trap has been triggered !");
		for i = 1, Amount do
			coroutine.resume(coroutine.create(function() PrepareHand() end))
			wait(.5);
		end
	end

	function Allowed() 
		if Regen then
			if not Used then
				return true;
			end
		else
			if not Used then
				Used 				=	true;				
				return true;
			end
		end

		return false;
	end

	local Network 					=	game:GetService('ServerStorage'):WaitForChild('Network').Deathrun.Traps.ActivateTrapRequest;

	Network.Event:connect(function(Trap, Button)
		if Trap.Name == script.Parent.Name then
			coroutine.resume(coroutine.create(function()
				Trigger();
			end))


			if Regen then
				Button.BrickColor 	=	BrickColor.new("Deep orange");
				Button.Decal.Texture=	"http://www.roblox.com/asset/?id=230646172"

				wait(Cooldown);

				Button.BrickColor 	=	BrickColor.new("Camo");
				Button.Decal.Texture=	"";
			else
				Button.BrickColor 	=	BrickColor.new("Really red");
			end

			return true;
		elseif Trap.Name == script.Parent.Name then
			print("Sorry, we are not allowed to Trigger this trap.");
		end

		return false;
	end)
