	local floaty=floaty or 0
	local timer=timer or 2
	local p=Instance.new("Part")
	p.Name="EffectFlare"
	p.Transparency=1
	p.TopSurface="Smooth"
	p.BottomSurface="Smooth"
	p.formFactor="Custom"
	p.Size=Vector3.new(.4,.4,.4)
