repeat wait() until script.Parent.Cylinder:FindFirstChild("soundActivate") ~= nil

Activated = false
Debounce = false

function outQuad(t, b, c, d)
  t = t / d
  return -c * t * (t - 2) + b
end

function OnTouch(part)
	if Activated == false then
		if part.Parent:findFirstChild("Humanoid")~=nil then
			if game.Players:findFirstChild(part.Parent.Name)~=nil then
				local User	 		=	game.Players:findFirstChild(part.Parent.Name)

				-- Fire our Fireworks
				if User.Character then
					if User.Character == part.Parent then
						if Debounce == false then
							Debounce = true

							print("Launcher activated by "..User.Name)
							--Verstuur informatie naar eventCheckpoints
							Activated = true

							script.Triggered.Value	= true

							script.Parent.Cylinder.soundActivate:Play()
							delay(0,LaunchFireworks)

							for i = 0,1,0.05 do

								local a = outQuad(i, 0, 1, 1)

								script.Parent.Cylinder.Transparency = a

								script.Parent.Cylinder.Mesh.Scale = Vector3.new(1.24, (2.2-(a*0.7)), 1.24)
								script.Parent.CylinderB.Mesh.Scale = Vector3.new(1.23, (2.16-(a*0.7)), 1.23)

								script.Parent.Cylinder.PointLight.Range = 12-(12*a)
								script.Parent.CylinderB.PointLight.Range = (12*a)

								wait(.05)
							end

							Debounce = false
						end
					end
				end

				-- Fire our Remote
				game:GetService('ServerStorage').Network.Deathrun.Notifactions.RequestNotifaction:Fire(User, 'Checkpoint');
			end
		end
	end
end


function LaunchFireworks()
	local a = script.Parent.Parent.Launchers:GetChildren()
	for i = 1,#a do
		if a[i]:FindFirstChild("Trigger") ~= nil then
			a[i].Trigger.Value = not a[i].Trigger.Value
		end
	end
end


script.Parent.Cylinder.Touched:connect(OnTouch)
