function PlaceIceSpike()
	local Sp = script.Parent.SpikeSpawn
	local Spike = game.ServerStorage.Assets.IceCavern.IceSpike:clone()

	local P = game.Players:GetChildren()
	local PossibleBlocks = {}
	for i = 1, #P do
		if P[i].TeamColor.Name == game:GetService("Teams").Runners.TeamColor.Name then
			if P[i].Character then
				local T = P[i].Character:findFirstChild("Torso")
				if T~=nil then
					local Front = (T.CFrame*CFrame.new(0, 0, -T.Velocity.magnitude/2)).p
					local Start = Front+Vector3.new(0, 15, 0)
					local End = Front+Vector3.new(0, -40, 0)
					local Line = Ray.new(Start, (End-Start).unit*55)
					local PMods = GetPlayerModels()
					PMods[#PMods+1] = Sp 
					local HitBlock, HitPos = game.workspace:FindPartOnRayWithIgnoreList(Line, PMods, false)
					if HitBlock~=nil then
						if HitBlock.Parent.Name == "Platform" then
							PossibleBlocks[#PossibleBlocks+1] = T
						end
					end
				end
			end
		end
	end
	local CF = nil
	if #PossibleBlocks >= 0 and math.random() < .33 then
		local ChosenBlock = PossibleBlocks[math.random(1, #PossibleBlocks)]
		local Front = (ChosenBlock.CFrame*CFrame.new(0, 0, -ChosenBlock.Velocity.magnitude/4-math.random()*8)).p
		local Start = Front+Vector3.new(0, 15, 0)
		local End = Front+Vector3.new(0, -40, 0)
		local Line = Ray.new(Start, (End-Start).unit*55)
		local PMods = GetPlayerModels()
		PMods[#PMods+1] = Sp
		local HitBlock, HitPos = game.workspace:FindPartOnRayWithIgnoreList(Line, PMods, false)
		local HitBlock2, HitPos2 = game.workspace:FindPartOnRayWithIgnoreList(Line, GetPlayerModels(), false)
		if HitBlock~=nil and HitBlock2~=nil then
			if HitBlock.Parent.Name == "Platform" and HitBlock2.Name == "SpikeSpawn" then
				CF = CFrame.new(HitPos.X, HitPos.Y, HitPos.Z)*CFrame.Angles(0, math.pi*2*math.random(), 0)
					*CFrame.Angles(math.pi/8*math.random(), 0, 0)*CFrame.new(0, -Spike.Size.Y/2, 0)
			end
		end
	else
		local Tries = 0
		repeat
			local Success = false
			Tries = Tries+1
			local Start = (Sp.CFrame*CFrame.new(Sp.Size.X*(math.random()-.5), 15, Sp.Size.Z*(math.random()-.5))).p
			local End = Start+Vector3.new(0, -55, 0)
			local Line = Ray.new(Start, (End-Start).unit*55)
			local PMods = GetPlayerModels()
			PMods[#PMods+1] = Sp
			local HitBlock, HitPos = game.workspace:FindPartOnRayWithIgnoreList(Line, PMods, false)
			if HitBlock~=nil then
				if HitBlock.Parent.Name == "Platform" then
					CF = CFrame.new(HitPos.X, HitPos.Y, HitPos.Z)*CFrame.Angles(0, math.pi*2*math.random(), 0)
						*CFrame.Angles(math.pi/8*math.random(), 0, 0)*CFrame.new(0, -Spike.Size.Y/2, 0)
					Success = true
				end
			end
		until Success == true or Tries >= 10
	end
	if CF~=nil then
		local C = Spike:clone()
		C.BrickColor = BrickColor.new(({"Bright blue", "Bright violet", "Lavender", "Bright bluish green",
			"Toothpaste", "Pastel violet", "Medium blue"})[math.random(1, 7)])
		C.CFrame = CFrame.new(CF.X, CF.Y, CF.Z)*(CF-CF.p)
		C.Touched:connect(function(hit)
			if hit.Parent:findFirstChild("Humanoid")~=nil then
				hit.Parent:findFirstChild("Humanoid").Health = 0
			end
		end)
		C.Parent = script.Parent
		for l = 1, 10 do
			wait()
			C.CFrame = C.CFrame*CFrame.new(0, C.Size.Y/11, 0) -- make sure it still sticks into the ground a bit
		end
		wait(1.5)
		for l = 1, 10 do
			wait()
			C.CFrame = C.CFrame*CFrame.new(0, -C.Size.Y/11, 0) -- make sure it still sticks into the ground a bit
		end
		C:Destroy()
	end
end

