function KillPlayersInArea(E)
	local P = game.Players:GetPlayers()
	for i = 1, #P do
		if P[i].Character then
			if P[i].Character:findFirstChild("HumanoidRootPart")~=nil then
				local HRP = P[i].Character:findFirstChild("HumanoidRootPart")
				local CF = CFrame.new(HRP.Position.X, HRP.Position.Y, HRP.Position.Z)*(E.CFrame-E.CFrame.p)*CFrame.new(0, -70, 0)
				local Start = HRP.Position
				local End = CF.p
				local Line = Ray.new(Start, (End-Start).unit*(Start-End).magnitude)
				local Ignores = GetPlayerModels()
				local B = script.Parent.SnowEmitters:GetChildren()
				for c = 1, #B do
