		Ex.BlastRadius = 0
		Ex.BlastPressure = 0
		Ex.DestroyJointRadiusPercent = 0
		Ex.Position = Vector3.new(F[e].Position.X, F[e].Position.Y, F[e].Position.Z)
		Ex.Parent = F[e]
	end
	for i = 1, #P do
		if P[i].Character then
			if P[i].Character:findFirstChild("Torso")~=nil then
				local T = P[i].Character:findFirstChild("Torso")

				local F = script.Parent.MagnitudeChecks:GetChildren()
				local Con = true
				for e = 1, #F do
					if (F[e].Position-T.Position).magnitude < 15 then
						P[i].Character:findFirstChild("Humanoid").Health = 0
						Con = false
					end
				end

				if Con == true then
					local Start = T.Position
					local End = T.Position+Vector3.new(0, -30, 0)
					local Line = Ray.new(Start, (End-Start).unit*30)
					local Ignores = GetPlayerModels()
					local HitBlock, HitPos = game.workspace:FindPartOnRayWithIgnoreList(Line, Ignores, false)
					if HitBlock~=nil then
						if HitBlock.Parent.Name == "KnockbackArea" or HitBlock.Parent.Name == "HideRock" then
							local P1, P2 = HitBlock.Position, (HitBlock.CFrame*CFrame.new(0, -1, -2)).p
							local Offset = P2-P1

							game.ReplicatedStorage.Network.Deathrun.Effects.RequestEffect:FireClient(P[i], "Explosion", Offset, 1600000, 30)
						end
					end
				end
			end
		end
	end
