function makerandombang()
	local bang=Instance.new("Sound")
	debris:AddItem(bang,10)
	bang.Volume=1
	bang.Pitch=.8+math.random()*.4
	bang.SoundId="http://www.roblox.com/asset/?id="..bangsounds[math.random(1,3)]
	return bang
