function Capture()
	local NetClone = game.ServerStorage.Assets.CorruptedJungle.Net:clone()
	local P = game.Players:GetPlayers()
	for i = 1, #P do
		if P[i].Character then
			local T = FindTorso(P[i].Character)
			if T~=nil then
				local Start = T.Position+Vector3.new(0, 4, 0)
				local End = T.Position+Vector3.new(0, -20, 0)
				local Line = Ray.new(Start, (End-Start).unit*24)
				local HitBlock, HitPos = game.workspace:FindPartOnRayWithIgnoreList(Line, GetPlayerModels(), false)
				if HitBlock~=nil then
					if HitBlock.Name == "NetCheck" then
						local Net = NetClone:clone()
						Net.Parent = game.Workspace
						local W = Instance.new("Weld")
						W.Name = "NetWeld"
						W.Part0 = T
						W.Part1 = Net
						W.C0 = CFrame.new(0, 0, 0)
						W.C1 = CFrame.new(0, 0, 0)
						W.Parent = T
						if P[i].Character:findFirstChild("Humanoid")~=nil then
							--P[i].Character.Humanoid:ChangeState("Ragdoll")

							game.ReplicatedStorage.Network.Deathrun.Effects.RequestEffect:FireClient(P[i], "Ragdoll")
