	p.Name="EffectFlare"
	p.Transparency=1
	p.TopSurface="Smooth"
	p.BottomSurface="Smooth"
	p.formFactor="Custom"
	p.Size=Vector3.new(.4,.4,.4)
	p.CanCollide=false
