		s.SparkleColor=Color3.new(1,.5,0)
		s3.SparkleColor=Color3.new(1,.5,0)
		f.Color=Color3.new(1,.5,0)
	end

	if floaty>0 then
		local bf=Instance.new("BodyForce")
		bf.force=Vector3.new(0,p:GetMass()*196.2*floaty,0)
		bf.Parent=p
	end
